/// Streaming Bernoulli naïve Bayes (river `naive_bayes.BernoulliNB`).
///
/// Class count is not identification `p`. Features are treated as
/// \(\{0,1\}\) via a \(0.5\) threshold.
#[derive(Clone, Debug)]
pub struct OnlineBernoulliNb {
    /// Additive smoothing.
    pub alpha: f64,
    classes: Vec<i64>,
    ones: Matrix,
    class_n: Vec<f64>,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for OnlineBernoulliNb {
    fn default() -> Self {
        Self {
            alpha: 1.0,
            classes: Vec::new(),
            ones: Matrix::zeros(0, 0),
            class_n: Vec::new(),
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl OnlineBernoulliNb {
    /// Empty Bernoulli NB.
    pub fn new() -> Self {
        Self::default()
    }
}

impl PartialFit for OnlineBernoulliNb {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no labels"),
            );
        };
        let p = x.ncols();
        if self.initialized && self.ones.ncols() != p {
            ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
            return finish_explain(
                ctx,
                reject_explain(
                    self.updates,
                    x.nrows(),
                    self.n_seen,
                    "feature space changed",
                ),
            );
        }
        let before = self.n_seen;
        for i in 0..x.nrows() {
            if !y[i].is_finite() {
                continue;
            }
            let lab = y[i].round() as i64;
            let idx = if let Some(t) = self.classes.iter().position(|&c| c == lab) {
                t
            } else {
                self.classes.push(lab);
                self.class_n.push(0.0);
                let k = self.classes.len();
                let mut nc = Matrix::zeros(k, p);
                for r in 0..self.ones.nrows() {
                    for c in 0..p.min(self.ones.ncols()) {
                        nc.set(r, c, self.ones.get(r, c));
                    }
                }
                self.ones = nc;
                self.initialized = true;
                k - 1
            };
            self.class_n[idx] += 1.0;
            for j in 0..p {
                if x.get(i, j) > 0.5 {
                    self.ones.set(idx, j, self.ones.get(idx, j) + 1.0);
                }
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates - 1, x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some((self.n_seen - before) as f64);
        q.information_gain = Some((self.n_seen - before) as f64);
        q.still_identified = self.classes.len() >= 2 && self.n_seen >= 2;
        q.warmup = self.n_seen < 4;
        q.explanation = format!("online BernoulliNB on {} rows", x.nrows());
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "class-conditional Bernoulli ones counts",
                "threshold features at 0.5 and accumulate",
                format!("n={before}"),
                format!("n={}", self.n_seen),
            ),
        )
    }
}

impl Predict for OnlineBernoulliNb {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        if !self.initialized || self.classes.is_empty() {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        let k = self.classes.len();
        let p = self.ones.ncols();
        let tot: f64 = self.class_n.iter().sum();
        let alpha = self.alpha.max(0.0);
        let y = Vector::from_iter((0..x.nrows()).map(|i| {
            let mut best = 0usize;
            let mut bv = f64::NEG_INFINITY;
            for c in 0..k {
                let mut s = ((self.class_n[c] + alpha) / (tot + alpha * k as f64)).ln();
                for j in 0..x.ncols().min(p) {
                    let phat =
                        (self.ones.get(c, j) + alpha) / (self.class_n[c] + 2.0 * alpha).max(1e-12);
                    let phat = phat.clamp(1e-12, 1.0 - 1e-12);
                    let on = if x.get(i, j) > 0.5 { 1.0 } else { 0.0 };
                    s += on * phat.ln() + (1.0 - on) * (1.0 - phat).ln();
                }
                if s > bv {
                    bv = s;
                    best = c;
                }
            }
            self.classes[best] as f64
        }));
        ctx.finish(y)
    }
}

/// Exponentially weighted average of a mean expert and a last-value expert
/// (river `optim.EWARegressor` lite).
///
/// Features are ignored; the mix is a two-expert forecast of the target.
#[derive(Clone, Debug)]
pub struct EwaRegressor {
    /// Multiplicative weight step \(\eta > 0\).
    pub eta: f64,
    w_mean: f64,
    w_last: f64,
    mean: f64,
    last: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for EwaRegressor {
    fn default() -> Self {
        Self {
            eta: 0.5,
            w_mean: 1.0,
            w_last: 1.0,
            mean: 0.0,
            last: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl EwaRegressor {
    /// EWA mix with step `eta`.
    pub fn new(eta: f64) -> Self {
        Self {
            eta,
            ..Self::default()
        }
    }

    fn mix(&self) -> f64 {
        let z = self.w_mean + self.w_last;
        if z <= 0.0 {
            self.mean
        } else {
            (self.w_mean * self.mean + self.w_last * self.last) / z
        }
    }
}

impl PartialFit for EwaRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no labels"),
            );
        };
        let eta = if self.eta.is_finite() && self.eta > 0.0 {
            self.eta
        } else {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message(format!(
                        "EwaRegressor.eta={} is not positive; using 0.5",
                        self.eta
                    ))
                    .build(),
            );
            0.5
        };
        ctx.push(
            Issue::builder(IssueCode::CausalClaimUnidentified)
                .severity(Severity::Advisory)
                .message(
                    "EwaRegressor mixes a running-mean expert and a last-value expert; x is unused",
                )
                .compromise(NumericalCompromise::new(
                    "feature-conditioned expert mix",
                    "two target-only experts with multiplicative weights",
                    "no model of x → y is identified",
                    "read the mix as an online forecast of y, not a feature effect",
                ))
                .build(),
        );
        let before = self.mix();
        for i in 0..x.nrows().min(y.len()) {
            if !y[i].is_finite() {
                continue;
            }
            let yt = y[i];
            if self.initialized {
                let e_mean = (self.mean - yt) * (self.mean - yt);
                let e_last = (self.last - yt) * (self.last - yt);
                self.w_mean *= (-eta * e_mean).exp();
                self.w_last *= (-eta * e_last).exp();
                let z = (self.w_mean + self.w_last).max(1e-18);
                self.w_mean = (self.w_mean / z).max(1e-12);
                self.w_last = (self.w_last / z).max(1e-12);
                let n = self.n_seen as f64;
                self.mean = (self.mean * n + yt) / (n + 1.0);
                self.last = yt;
            } else {
                self.mean = yt;
                self.last = yt;
                self.initialized = true;
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let after = self.mix();
        let mut q = IncrementalQuality::new(self.updates - 1, x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some((after - before).abs());
        q.information_gain = Some((after - before).abs().max(1.0 / self.n_seen.max(1) as f64));
        q.still_identified = self.initialized && self.n_seen >= 2;
        q.warmup = self.n_seen < 2;
        q.explanation = format!("EWA mix after {} rows, pred={after:.6e}", x.nrows());
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "mean/last expert weights",
                "multiplicative loss update, then renormalize",
                format!("mix={before:.6e}"),
                format!("mix={after:.6e}"),
            ),
        )
    }
}

impl Predict for EwaRegressor {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        let m = self.mix();
        ctx.finish(Vector::from_iter((0..x.nrows()).map(|_| m)))
    }
}

/// Running-quantile clip (river `anomaly.QuantileFilter` / winsorize).
///
/// Values above the empirical `q`-quantile of a 256-row window are clipped
/// to that quantile. `q` is not identification `p`.
#[derive(Clone, Debug)]
pub struct QuantileFilter {
    /// Upper quantile in \((0, 1)\).
    pub q: f64,
    window: Vec<f64>,
    n_seen: u64,
    updates: u64,
}

impl Default for QuantileFilter {
    fn default() -> Self {
        Self {
            q: 0.95,
            window: Vec::new(),
            n_seen: 0,
            updates: 0,
        }
    }
}

impl QuantileFilter {
    /// Filter at quantile `q`.
    pub fn new(q: f64) -> Self {
        Self {
            q,
            ..Self::default()
        }
    }

    fn quantile(&self, q: f64) -> f64 {
        if self.window.is_empty() {
            return f64::NAN;
        }
        let mut xs = self.window.clone();
        xs.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let idx = ((q.clamp(0.0, 1.0)) * (xs.len() - 1) as f64).round() as usize;
        xs[idx.min(xs.len() - 1)]
    }
}

impl PartialFit for QuantileFilter {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let qv = if self.q.is_finite() && self.q > 0.0 && self.q < 1.0 {
            self.q
        } else {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message(format!(
                        "QuantileFilter.q={} is not in (0,1); using 0.95",
                        self.q
                    ))
                    .build(),
            );
            0.95
        };
        let before = self.quantile(qv);
        for i in 0..x.nrows() {
            for j in 0..x.ncols() {
                let v = x.get(i, j);
                if v.is_finite() {
                    self.window.push(v);
                    if self.window.len() > 256 {
                        self.window.remove(0);
                    }
                    self.n_seen += 1;
                }
            }
        }
        self.updates += 1;
        let after = self.quantile(qv);
        let mut q = IncrementalQuality::new(self.updates - 1, x.nrows(), self.n_seen);
        q.effective_sample_size = self.window.len() as f64;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.window.len() >= 4;
        q.warmup = self.window.len() < 4;
        q.explanation = format!("QuantileFilter q={qv:.3} threshold={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "empirical upper quantile",
                "256-row sliding window order statistic",
                format!("q={before:.6e}"),
                format!("q={after:.6e}"),
            ),
        )
    }
}

impl Transform for QuantileFilter {
    fn transform(&self, x: &Matrix, session: &Session) -> Result<Qualified<Matrix>> {
        let mut ctx = FitCtx::with_session(session.child("transform"));
        if self.window.is_empty() {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(x.clone());
        }
        let qv = if self.q.is_finite() && self.q > 0.0 && self.q < 1.0 {
            self.q
        } else {
            0.95
        };
        let cap = self.quantile(qv);
        let out = Matrix::from_fn(x.nrows(), x.ncols(), |i, j| {
            let v = x.get(i, j);
            if v.is_finite() && v > cap {
                cap
            } else {
                v
            }
        });
        ctx.finish(out)
    }
}

/// Streaming RMSE (river `metrics.RMSE`).
#[derive(Clone, Debug, Default)]
pub struct OnlineRmse {
    sse: f64,
    n: u64,
    updates: u64,
}

impl OnlineRmse {
    /// Empty RMSE.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current RMSE, or NaN when empty.
    pub fn score(&self) -> f64 {
        if self.n == 0 {
            f64::NAN
        } else {
            (self.sse / self.n as f64).sqrt()
        }
    }
}

impl PartialFit for OnlineRmse {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        metric_partial(
            session,
            "rmse",
            x,
            y,
            self.updates,
            self.n,
            |pred, truth| {
                let e = pred - truth;
                self.sse += e * e;
                self.n += 1;
                self.updates += 1;
                self.score()
            },
        )
    }
}

/// Streaming Cohen's κ (river `metrics.CohenKappa`).
#[derive(Clone, Debug, Default)]
pub struct OnlineCohenKappa {
    a: f64,
    b: f64,
    c: f64,
    d: f64,
    updates: u64,
}

impl OnlineCohenKappa {
    /// Empty κ.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current κ, or NaN when empty.
    pub fn score(&self) -> f64 {
        let n = self.a + self.b + self.c + self.d;
        if n <= 0.0 {
            return f64::NAN;
        }
        let po = (self.a + self.d) / n;
        let pe = ((self.a + self.b) * (self.a + self.c) + (self.c + self.d) * (self.b + self.d))
            / (n * n);
        if (1.0 - pe).abs() <= 1e-18 {
            f64::NAN
        } else {
            (po - pe) / (1.0 - pe)
        }
    }
}

impl PartialFit for OnlineCohenKappa {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        metric_partial(
            session,
            "cohen_kappa",
            x,
            y,
            self.updates,
            (self.a + self.b + self.c + self.d) as u64,
            |pred, truth| {
                let p = pred > 0.5;
                let t = truth > 0.5;
                match (p, t) {
                    (false, false) => self.a += 1.0,
                    (true, false) => self.b += 1.0,
                    (false, true) => self.c += 1.0,
                    (true, true) => self.d += 1.0,
                }
                self.updates += 1;
                self.score()
            },
        )
    }
}

/// Exponentially weighted mean (river `stats.EWMean`).
#[derive(Clone, Debug)]
pub struct EwMean {
    /// Fade factor in \((0, 1]\). `1` is the expanding mean.
    pub fading: f64,
    mean: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for EwMean {
    fn default() -> Self {
        Self {
            fading: 0.5,
            mean: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl EwMean {
    /// EW mean with fade `fading`.
    pub fn new(fading: f64) -> Self {
        Self {
            fading,
            ..Self::default()
        }
    }

    /// Current mean, or NaN before the first update.
    pub fn score(&self) -> f64 {
        if self.initialized {
            self.mean
        } else {
            f64::NAN
        }
    }
}

impl PartialFit for EwMean {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let fade = if self.fading.is_finite() && self.fading > 0.0 && self.fading <= 1.0 {
            self.fading
        } else {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message(format!(
                        "EwMean.fading={} is not in (0,1]; using 0.5",
                        self.fading
                    ))
                    .build(),
            );
            0.5
        };
        let before = self.mean;
        for i in 0..x.nrows() {
            let v = x.get(i, 0);
            if !v.is_finite() {
                continue;
            }
            if !self.initialized {
                self.mean = v;
                self.initialized = true;
            } else if fade >= 1.0 {
                let n = self.n_seen as f64;
                self.mean = (self.mean * n + v) / (n + 1.0);
            } else {
                self.mean = fade * self.mean + (1.0 - fade) * v;
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates - 1, x.nrows(), self.n_seen);
        q.effective_sample_size = if fade >= 1.0 {
            self.n_seen as f64
        } else {
            (1.0 / (1.0 - fade)).min(self.n_seen as f64)
        };
        q.parameter_delta_norm = Some((self.mean - before).abs());
        q.information_gain = Some(
            (self.mean - before)
                .abs()
                .max(1.0 / self.n_seen.max(1) as f64),
        );
        q.still_identified = self.initialized;
        q.warmup = self.n_seen < 2;
        q.explanation = format!("EWMean fade={fade:.3} mean={:.6e}", self.mean);
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "exponentially weighted mean",
                "fade previous mean and fold in the new observation",
                format!("mean={before:.6e}"),
                format!("mean={:.6e}", self.mean),
            ),
        )
    }
}

impl Predict for EwMean {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        ctx.finish(Vector::from_iter((0..x.nrows()).map(|_| self.mean)))
    }
}

/// Degree-2 polynomial expander (river `preprocessing.PolynomialExtender`).
///
/// Expanded width is not identification `p`.
#[derive(Clone, Debug)]
pub struct PolynomialExtender {
    /// Polynomial degree (`1` or `2`).
    pub degree: usize,
    n_in: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for PolynomialExtender {
    fn default() -> Self {
        Self {
            degree: 2,
            n_in: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl PolynomialExtender {
    /// Expander of the given degree.
    pub fn new(degree: usize) -> Self {
        Self {
            degree,
            ..Self::default()
        }
    }
}

impl PartialFit for PolynomialExtender {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let deg = if self.degree == 1 || self.degree == 2 {
            self.degree
        } else {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message(format!(
                        "PolynomialExtender.degree={} is not 1 or 2; using 2",
                        self.degree
                    ))
                    .build(),
            );
            2
        };
        self.degree = deg;
        if x.ncols() == 0 {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no features"),
            );
        }
        if !self.initialized {
            self.n_in = x.ncols();
            self.initialized = true;
        } else if self.n_in != x.ncols() {
            ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
            return finish_explain(
                ctx,
                reject_explain(
                    self.updates,
                    x.nrows(),
                    self.n_seen,
                    "feature space changed",
                ),
            );
        }
        let p = x.ncols();
        let out_p = if deg == 1 { p } else { p + p + p * (p + 1) / 2 };
        if out_p > 64 {
            ctx.push(
                Issue::builder(IssueCode::PolynomialExplosion)
                    .message(format!("PolynomialExtender maps {p} → {out_p} columns"))
                    .compromise(NumericalCompromise::new(
                        "identified low-order features",
                        "degree-2 monomials including interactions",
                        "the expanded map is wider than a small panel",
                        "do not treat every cross-term as an identified effect",
                    ))
                    .build(),
            );
        }
        self.n_seen += x.nrows() as u64;
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates - 1, x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(0.0);
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.initialized;
        q.warmup = self.n_seen < 2;
        q.explanation = format!("PolynomialExtender degree={deg} on {} rows", x.nrows());
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "polynomial feature map",
                "record input width; expansion is stateless",
                format!("n_in={}", self.n_in),
                format!("n_in={} n={}", self.n_in, self.n_seen),
            ),
        )
    }
}

impl Transform for PolynomialExtender {
    fn transform(&self, x: &Matrix, session: &Session) -> Result<Qualified<Matrix>> {
        let mut ctx = FitCtx::with_session(session.child("transform"));
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(x.clone());
        }
        let p = x.ncols().min(self.n_in);
        let deg = if self.degree == 1 { 1 } else { 2 };
        let out_p = if deg == 1 { p } else { p + p + p * (p + 1) / 2 };
        let out = Matrix::from_fn(x.nrows(), out_p, |i, j| {
            if j < p {
                return x.get(i, j);
            }
            if j < 2 * p {
                let v = x.get(i, j - p);
                return v * v;
            }
            let mut k = j - 2 * p;
            for a in 0..p {
                let n_right = p - a;
                if k < n_right {
                    let b = a + k;
                    return x.get(i, a) * x.get(i, b);
                }
                k -= n_right;
            }
            0.0
        });
        ctx.finish(out)
    }
}

/// Online target-mean encoder (river `preprocessing.TargetEncoder` / `stats.Mean`).
#[derive(Clone, Debug)]
pub struct TargetMeanEncoder {
    maps: Vec<HashMap<i64, (f64, f64)>>,
    global: f64,
    global_n: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for TargetMeanEncoder {
    fn default() -> Self {
        Self {
            maps: Vec::new(),
            global: 0.0,
            global_n: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl TargetMeanEncoder {
    /// Empty target-mean encoder.
    pub fn new() -> Self {
        Self::default()
    }
}

impl PartialFit for TargetMeanEncoder {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no labels"),
            );
        };
        if !self.initialized {
            self.maps = vec![HashMap::new(); x.ncols()];
            self.initialized = true;
        } else if self.maps.len() != x.ncols() {
            ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
            return finish_explain(
                ctx,
                reject_explain(
                    self.updates,
                    x.nrows(),
                    self.n_seen,
                    "feature space changed",
                ),
            );
        }
        let before = self.global;
        for i in 0..x.nrows().min(y.len()) {
            if !y[i].is_finite() {
                continue;
            }
            self.global_n += 1.0;
            self.global += (y[i] - self.global) / self.global_n;
            for j in 0..x.ncols() {
                let v = x.get(i, j);
                if !v.is_finite() {
                    continue;
                }
                let key = v.round() as i64;
                let e = self.maps[j].entry(key).or_insert((0.0, 0.0));
                e.1 += 1.0;
                e.0 += (y[i] - e.0) / e.1;
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates - 1, x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some((self.global - before).abs());
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n_seen >= 2;
        q.warmup = self.n_seen < 4;
        q.explanation = format!("TargetMeanEncoder global={:.6e}", self.global);
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "per-level target means",
                "Welford update of category-conditional means",
                format!("global={before:.6e}"),
                format!("global={:.6e}", self.global),
            ),
        )
    }
}

impl Transform for TargetMeanEncoder {
    fn transform(&self, x: &Matrix, session: &Session) -> Result<Qualified<Matrix>> {
        let mut ctx = FitCtx::with_session(session.child("transform"));
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(x.clone());
        }
        let out = Matrix::from_fn(x.nrows(), x.ncols(), |i, j| {
            let v = x.get(i, j);
            if !v.is_finite() {
                return self.global;
            }
            if j >= self.maps.len() {
                return self.global;
            }
            self.maps[j]
                .get(&(v.round() as i64))
                .map(|e| e.0)
                .unwrap_or(self.global)
        });
        ctx.finish(out)
    }
}

/// Poisson-bootstrap bag of perceptrons (river `ensemble.BaggingClassifier`).
#[derive(Clone, Debug)]
pub struct OnlineBagging {
    /// Members.
    pub n_models: usize,
    models: Vec<Perceptron>,
    n_seen: u64,
    updates: u64,
    rng: Rng,
}

impl Default for OnlineBagging {
    fn default() -> Self {
        Self {
            n_models: 3,
            models: Vec::new(),
            n_seen: 0,
            updates: 0,
            rng: Rng::new(3),
        }
    }
}

impl OnlineBagging {
    /// Bag of `n_models` perceptrons.
    pub fn new(n_models: usize) -> Self {
        Self {
            n_models: n_models.max(1),
            ..Self::default()
        }
    }
}

impl PartialFit for OnlineBagging {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no labels"),
            );
        };
        if self.models.is_empty() {
            self.models = vec![Perceptron::new(); self.n_models.max(1)];
        }
        let before = self.n_seen;
        for m in 0..self.models.len() {
            let mut rows: Vec<usize> = Vec::new();
            for i in 0..x.nrows().min(y.len()) {
                let k = self.rng.poisson(1.0) as usize;
                for _ in 0..k {
                    rows.push(i);
                }
            }
            if rows.is_empty() && x.nrows() > 0 {
                rows.push(0);
            }
            if rows.is_empty() {
                continue;
            }
            let xb = Matrix::from_fn(rows.len(), x.ncols(), |r, c| x.get(rows[r], c));
            let yb = Vector::from_iter(rows.iter().map(|&i| y[i]));
            let _ = self.models[m].partial_fit(&xb, Some(&yb), &session.child(format!("bag_{m}")));
        }
        self.n_seen += x.nrows() as u64;
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates - 1, x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some((self.n_seen - before) as f64);
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n_seen >= 2;
        q.warmup = self.n_seen < 4;
        q.explanation = format!(
            "OnlineBagging {} perceptrons, Poisson bootstrap",
            self.models.len()
        );
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "perceptron committee",
                "each member sees a Poisson(1) bootstrap of the batch",
                format!("n={before}"),
                format!("n={}", self.n_seen),
            ),
        )
    }
}

impl Predict for OnlineBagging {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        if self.models.is_empty() {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        let mut acc = vec![0.0; x.nrows()];
        let mut k: f64 = 0.0;
        for (t, m) in self.models.iter().enumerate() {
            match m.predict(x, &session.child(format!("p{t}"))) {
                Ok(q) => {
                    for i in 0..x.nrows().min(q.value.len()) {
                        acc[i] += q.value[i];
                    }
                    k += 1.0;
                }
                Err(_) => {}
            }
        }
        let k = k.max(1.0);
        ctx.finish(Vector::from_iter(acc.iter().map(|v| {
            if *v / k > 0.5 {
                1.0
            } else {
                0.0
            }
        })))
    }
}

/// Rolling quantile (river `stats.Quantile`).
#[derive(Clone, Debug)]
pub struct RollingQuantile {
    /// Quantile in \((0, 1)\).
    pub q: f64,
    window: Vec<f64>,
    n_seen: u64,
    updates: u64,
}

impl Default for RollingQuantile {
    fn default() -> Self {
        Self {
            q: 0.5,
            window: Vec::new(),
            n_seen: 0,
            updates: 0,
        }
    }
}

impl RollingQuantile {
    /// Rolling quantile `q`.
    pub fn new(q: f64) -> Self {
        Self {
            q,
            ..Self::default()
        }
    }

    /// Current quantile, or NaN when empty.
    pub fn score(&self) -> f64 {
        if self.window.is_empty() {
            return f64::NAN;
        }
        let qv = if self.q.is_finite() && self.q > 0.0 && self.q < 1.0 {
            self.q
        } else {
            0.5
        };
        let mut xs = self.window.clone();
        xs.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let idx = (qv * (xs.len() - 1) as f64).round() as usize;
        xs[idx.min(xs.len() - 1)]
    }
}

impl PartialFit for RollingQuantile {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.q.is_finite() || self.q <= 0.0 || self.q >= 1.0 {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message(format!(
                        "RollingQuantile.q={} is not in (0,1); using 0.5",
                        self.q
                    ))
                    .build(),
            );
            self.q = 0.5;
        }
        let before = self.score();
        for i in 0..x.nrows() {
            let v = x.get(i, 0);
            if v.is_finite() {
                self.window.push(v);
                if self.window.len() > 256 {
                    self.window.remove(0);
                }
                self.n_seen += 1;
            }
        }
        self.updates += 1;
        let after = self.score();
        let mut q = IncrementalQuality::new(self.updates - 1, x.nrows(), self.n_seen);
        q.effective_sample_size = self.window.len() as f64;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.window.len() >= 4;
        q.warmup = self.window.len() < 4;
        q.explanation = format!("RollingQuantile q={:.3} value={after:.6e}", self.q);
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "windowed order statistic",
                "256-row sliding quantile",
                format!("q={before:.6e}"),
                format!("q={after:.6e}"),
            ),
        )
    }
}

/// Streaming Hamming loss (river `metrics.Hamming`).
#[derive(Clone, Debug, Default)]
pub struct OnlineHamming {
    bad: f64,
    n: u64,
    updates: u64,
}

impl OnlineHamming {
    /// Empty Hamming.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current Hamming loss, or NaN when empty.
    pub fn score(&self) -> f64 {
        if self.n == 0 {
            f64::NAN
        } else {
            self.bad / self.n as f64
        }
    }
}

impl PartialFit for OnlineHamming {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        metric_partial(
            session,
            "hamming",
            x,
            y,
            self.updates,
            self.n,
            |pred, truth| {
                self.n += 1;
                if pred.round() != truth.round() {
                    self.bad += 1.0;
                }
                self.updates += 1;
                self.score()
            },
        )
    }
}

/// Streaming Jaccard index (river `metrics.Jaccard`).
#[derive(Clone, Debug, Default)]
pub struct OnlineJaccard {
    inter: f64,
    union: f64,
    n: u64,
    updates: u64,
}

impl OnlineJaccard {
    /// Empty Jaccard.
    pub fn new() -> Self {
        Self::default()
    }

    /// Intersection over union, or NaN when empty.
    pub fn score(&self) -> f64 {
        if self.union <= 0.0 {
            f64::NAN
        } else {
            self.inter / self.union
        }
    }
}

impl PartialFit for OnlineJaccard {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        metric_partial(
            session,
            "jaccard",
            x,
            y,
            self.updates,
            self.n,
            |pred, truth| {
                let a = pred.round() != 0.0;
                let b = truth.round() != 0.0;
                if a && b {
                    self.inter += 1.0;
                }
                if a || b {
                    self.union += 1.0;
                }
                self.n += 1;
                self.updates += 1;
                self.score()
            },
        )
    }
}

/// Exponentially weighted variance (river `stats.EWVar`).
#[derive(Clone, Debug)]
pub struct EwVar {
    fading: f64,
    mean: f64,
    m2: f64,
    w: f64,
    n_seen: u64,
    updates: u64,
}

impl Default for EwVar {
    fn default() -> Self {
        Self {
            fading: 0.5,
            mean: 0.0,
            m2: 0.0,
            w: 0.0,
            n_seen: 0,
            updates: 0,
        }
    }
}

impl EwVar {
    /// EW variance with fading factor in `(0, 1]`.
    pub fn new(fading: f64) -> Self {
        Self {
            fading,
            ..Self::default()
        }
    }

    /// Current variance, or NaN during warmup.
    pub fn score(&self) -> f64 {
        if self.w <= 1e-12 {
            f64::NAN
        } else {
            self.m2 / self.w
        }
    }
}

impl PartialFit for EwVar {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let fade = if self.fading.is_finite() && self.fading > 0.0 && self.fading <= 1.0 {
            self.fading
        } else {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message(format!(
                        "EwVar fading={} is not in (0,1]; using 0.5",
                        self.fading
                    ))
                    .build(),
            );
            0.5
        };
        let before = self.score();
        for i in 0..x.nrows() {
            let v = x.get(i, 0);
            if !v.is_finite() {
                continue;
            }
            if self.w <= 0.0 {
                self.mean = v;
                self.m2 = 0.0;
                self.w = 1.0;
            } else {
                self.w = fade * self.w + 1.0;
                let d = v - self.mean;
                self.mean += d / self.w;
                self.m2 = fade * self.m2 + d * (v - self.mean);
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let after = self.score();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.w;
        q.parameter_delta_norm = Some((after - before).abs());
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n_seen >= 2;
        q.warmup = self.n_seen < 2;
        q.explanation = format!("EwVar fade={fade:.3} var={after:.6e}");
        q.loss_after = Some(after);
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "exponentially weighted second moment",
                "Welford update with geometric fading of past mass",
                format!("var={before:.6e}"),
                format!("var={after:.6e}"),
            ),
        )
    }
}

/// Successive-halving perceptron committee (river `model_selection.SuccessiveHalvingClassifier`).
///
/// Model count is not identification `p`. The worst half is dropped when
/// `n_seen` crosses successive powers of two.
#[derive(Clone, Debug)]
pub struct SuccessiveHalvingClassifier {
    /// Initial candidate count.
    pub n_models: usize,
    models: Vec<Perceptron>,
    hits: Vec<f64>,
    seen: Vec<f64>,
    n_seen: u64,
    updates: u64,
    cuts: u64,
}

impl Default for SuccessiveHalvingClassifier {
    fn default() -> Self {
        Self {
            n_models: 4,
            models: Vec::new(),
            hits: Vec::new(),
            seen: Vec::new(),
            n_seen: 0,
            updates: 0,
            cuts: 0,
        }
    }
}

impl SuccessiveHalvingClassifier {
    /// Committee of `n_models` perceptrons.
    pub fn new(n_models: usize) -> Self {
        Self {
            n_models: n_models.max(1),
            ..Self::default()
        }
    }

    /// Models still alive.
    pub fn n_alive(&self) -> usize {
        self.models.len()
    }
}

impl PartialFit for SuccessiveHalvingClassifier {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no labels"),
            );
        };
        if self.n_models < 2 {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message(format!(
                        "SuccessiveHalving n_models={} < 2; using 2",
                        self.n_models
                    ))
                    .build(),
            );
            self.n_models = 2;
        }
        if self.models.is_empty() {
            self.models = vec![Perceptron::new(); self.n_models.max(2)];
            self.hits = vec![0.0; self.models.len()];
            self.seen = vec![0.0; self.models.len()];
        }
        let before = self.n_seen;
        let n_before = self.models.len();
        for m in 0..self.models.len() {
            let pred = self.models[m]
                .predict(x, &session.child(format!("sh_pre_{m}")))
                .map(|q| q.value)
                .unwrap_or_else(|_| Vector::zeros(x.nrows()));
            for i in 0..x.nrows().min(y.len()).min(pred.len()) {
                if pred[i].round() == y[i].round() {
                    self.hits[m] += 1.0;
                }
                self.seen[m] += 1.0;
            }
            let _ = self.models[m].partial_fit(x, Some(y), &session.child(format!("sh_{m}")));
        }
        self.n_seen += x.nrows() as u64;
        self.updates += 1;
        let mut cut = false;
        if self.models.len() > 1
            && self.n_seen >= 2
            && (self.n_seen.is_power_of_two() || before < 2)
        {
            let mut order: Vec<usize> = (0..self.models.len()).collect();
            order.sort_by(|&a, &b| {
                let aa = if self.seen[a] > 0.0 {
                    self.hits[a] / self.seen[a]
                } else {
                    0.0
                };
                let bb = if self.seen[b] > 0.0 {
                    self.hits[b] / self.seen[b]
                } else {
                    0.0
                };
                bb.partial_cmp(&aa).unwrap_or(std::cmp::Ordering::Equal)
            });
            let keep = (self.models.len() / 2).max(1);
            let keep_idx = &order[..keep];
            let mut models = Vec::new();
            let mut hits = Vec::new();
            let mut seen = Vec::new();
            for &i in keep_idx {
                models.push(self.models[i].clone());
                hits.push(self.hits[i]);
                seen.push(self.seen[i]);
            }
            if models.len() < n_before {
                cut = true;
                self.cuts += 1;
            }
            self.models = models;
            self.hits = hits;
            self.seen = seen;
        }
        let best = self
            .hits
            .iter()
            .zip(&self.seen)
            .map(|(h, s)| if *s > 0.0 { h / s } else { 0.0 })
            .fold(0.0_f64, f64::max);
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(if cut { 1.0 } else { 0.0 });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n_seen >= 2 && !self.models.is_empty();
        q.warmup = self.n_seen < 4;
        q.explanation = format!(
            "SuccessiveHalving alive={} cuts={} best_acc={best:.3}",
            self.models.len(),
            self.cuts
        );
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                if cut {
                    "eliminated the worse half of the committee"
                } else {
                    "updated every surviving perceptron"
                },
                "rung promotions drop models with the lowest running accuracy",
                format!("alive={n_before} n={before}"),
                format!(
                    "alive={} n={} acc={best:.3}",
                    self.models.len(),
                    self.n_seen
                ),
            ),
        )
    }
}

impl Predict for SuccessiveHalvingClassifier {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        if self.models.is_empty() {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        let mut acc = vec![0.0; x.nrows()];
        let mut k: f64 = 0.0;
        for (t, m) in self.models.iter().enumerate() {
            match m.predict(x, &session.child(format!("shp_{t}"))) {
                Ok(q) => {
                    for i in 0..x.nrows().min(q.value.len()) {
                        acc[i] += q.value[i];
                    }
                    k += 1.0;
                }
                Err(_) => {}
            }
        }
        let k = k.max(1.0);
        ctx.finish(Vector::from_iter(acc.iter().map(|v| {
            if *v / k > 0.5 {
                1.0
            } else {
                0.0
            }
        })))
    }
}

/// Successive-halving RLS committee (river `model_selection.SuccessiveHalvingRegressor`).
#[derive(Clone, Debug)]
pub struct SuccessiveHalvingRegressor {
    /// Initial candidate count.
    pub n_models: usize,
    models: Vec<LinearRegression>,
    sse: Vec<f64>,
    n_err: Vec<f64>,
    n_seen: u64,
    updates: u64,
    cuts: u64,
}

impl Default for SuccessiveHalvingRegressor {
    fn default() -> Self {
        Self {
            n_models: 4,
            models: Vec::new(),
            sse: Vec::new(),
            n_err: Vec::new(),
            n_seen: 0,
            updates: 0,
            cuts: 0,
        }
    }
}

impl SuccessiveHalvingRegressor {
    /// Committee of `n_models` RLS estimators.
    pub fn new(n_models: usize) -> Self {
        Self {
            n_models: n_models.max(1),
            ..Self::default()
        }
    }
}

impl PartialFit for SuccessiveHalvingRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no labels"),
            );
        };
        if self.n_models < 2 {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message(format!(
                        "SuccessiveHalvingRegressor n_models={} < 2; using 2",
                        self.n_models
                    ))
                    .build(),
            );
            self.n_models = 2;
        }
        if self.models.is_empty() {
            self.models = (0..self.n_models.max(2))
                .map(|i| {
                    let mut m = LinearRegression::new(1.0);
                    m.p0 = 10.0 * (i as f64 + 1.0);
                    m.fit_intercept = true;
                    m
                })
                .collect();
            self.sse = vec![0.0; self.models.len()];
            self.n_err = vec![0.0; self.models.len()];
        }
        let before = self.n_seen;
        let n_before = self.models.len();
        for m in 0..self.models.len() {
            let pred = self.models[m]
                .predict(x, &session.child(format!("shr_pre_{m}")))
                .map(|q| q.value)
                .unwrap_or_else(|_| Vector::zeros(x.nrows()));
            for i in 0..x.nrows().min(y.len()).min(pred.len()) {
                let e = pred[i] - y[i];
                self.sse[m] += e * e;
                self.n_err[m] += 1.0;
            }
            let _ = self.models[m].partial_fit(x, Some(y), &session.child(format!("shr_{m}")));
        }
        self.n_seen += x.nrows() as u64;
        self.updates += 1;
        let mut cut = false;
        if self.models.len() > 1
            && self.n_seen >= 2
            && (self.n_seen.is_power_of_two() || before < 2)
        {
            let mut order: Vec<usize> = (0..self.models.len()).collect();
            order.sort_by(|&a, &b| {
                let aa = if self.n_err[a] > 0.0 {
                    self.sse[a] / self.n_err[a]
                } else {
                    f64::INFINITY
                };
                let bb = if self.n_err[b] > 0.0 {
                    self.sse[b] / self.n_err[b]
                } else {
                    f64::INFINITY
                };
                aa.partial_cmp(&bb).unwrap_or(std::cmp::Ordering::Equal)
            });
            let keep = (self.models.len() / 2).max(1);
            let keep_idx = &order[..keep];
            let mut models = Vec::new();
            let mut sse = Vec::new();
            let mut n_err = Vec::new();
            for &i in keep_idx {
                models.push(self.models[i].clone());
                sse.push(self.sse[i]);
                n_err.push(self.n_err[i]);
            }
            if models.len() < n_before {
                cut = true;
                self.cuts += 1;
            }
            self.models = models;
            self.sse = sse;
            self.n_err = n_err;
        }
        let best = self
            .sse
            .iter()
            .zip(&self.n_err)
            .map(|(s, n)| if *n > 0.0 { s / n } else { f64::INFINITY })
            .fold(f64::INFINITY, f64::min);
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(if cut { 1.0 } else { 0.0 });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n_seen >= 2 && !self.models.is_empty();
        q.warmup = self.n_seen < 4;
        q.explanation = format!(
            "SuccessiveHalvingRegressor alive={} cuts={} best_mse={best:.6e}",
            self.models.len(),
            self.cuts
        );
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                if cut {
                    "eliminated the worse half of the RLS committee"
                } else {
                    "updated every surviving RLS member"
                },
                "rung promotions drop models with the highest running MSE",
                format!("alive={n_before} n={before}"),
                format!(
                    "alive={} n={} mse={best:.6e}",
                    self.models.len(),
                    self.n_seen
                ),
            ),
        )
    }
}

impl Predict for SuccessiveHalvingRegressor {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        if self.models.is_empty() {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        let mut acc = vec![0.0; x.nrows()];
        let mut k: f64 = 0.0;
        for (t, m) in self.models.iter().enumerate() {
            match m.predict(x, &session.child(format!("shrp_{t}"))) {
                Ok(q) => {
                    for i in 0..x.nrows().min(q.value.len()) {
                        acc[i] += q.value[i];
                    }
                    k += 1.0;
                }
                Err(_) => {}
            }
        }
        let k = k.max(1.0);
        ctx.finish(Vector::from_iter(acc.iter().map(|v| v / k)))
    }
}

/// Aggregated Mondrian Forest lite (river `forest.AMFClassifier`).
///
/// Tree count is not identification `p`. Each tree grows at most one
/// axis-aligned stump once two labelled rows have been seen.
#[derive(Clone, Debug)]
pub struct AmfClassifier {
    /// Trees.
    pub n_trees: usize,
    trees: Vec<AmfTree>,
    n_seen: u64,
    updates: u64,
    rng: Rng,
}

#[derive(Clone, Debug)]
struct AmfTree {
    p: usize,
    n: u64,
    lo: Vector,
    hi: Vector,
    split_j: Option<usize>,
    split_t: f64,
    leaf: HashMap<i64, f64>,
    left: HashMap<i64, f64>,
    right: HashMap<i64, f64>,
}

impl Default for AmfClassifier {
    fn default() -> Self {
        Self {
            n_trees: 4,
            trees: Vec::new(),
            n_seen: 0,
            updates: 0,
            rng: Rng::new(29),
        }
    }
}

impl AmfClassifier {
    /// AMF with `n_trees` Mondrian stumps.
    pub fn new(n_trees: usize) -> Self {
        Self {
            n_trees: n_trees.max(1),
            ..Self::default()
        }
    }
}

fn amf_majority(counts: &HashMap<i64, f64>) -> f64 {
    counts
        .iter()
        .max_by(|a, b| {
            a.1.partial_cmp(b.1)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then(b.0.cmp(a.0))
        })
        .map(|(k, _)| *k as f64)
        .unwrap_or(0.0)
}

impl PartialFit for AmfClassifier {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no labels"),
            );
        };
        if self.trees.is_empty() {
            self.trees = (0..self.n_trees.max(1))
                .map(|_| AmfTree {
                    p: x.ncols(),
                    n: 0,
                    lo: Vector::filled(x.ncols(), f64::INFINITY),
                    hi: Vector::filled(x.ncols(), f64::NEG_INFINITY),
                    split_j: None,
                    split_t: 0.0,
                    leaf: HashMap::new(),
                    left: HashMap::new(),
                    right: HashMap::new(),
                })
                .collect();
        } else if self.trees[0].p != x.ncols() {
            ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
            return finish_explain(
                ctx,
                reject_explain(
                    self.updates,
                    x.nrows(),
                    self.n_seen,
                    "feature space changed",
                ),
            );
        }
        let before = self.n_seen;
        let mut splits = 0u64;
        for i in 0..x.nrows().min(y.len()) {
            if !y[i].is_finite() {
                continue;
            }
            let lab = y[i].round() as i64;
            for t in &mut self.trees {
                for j in 0..x.ncols().min(t.lo.len()) {
                    let v = x.get(i, j);
                    if v < t.lo[j] {
                        t.lo[j] = v;
                    }
                    if v > t.hi[j] {
                        t.hi[j] = v;
                    }
                }
                t.n += 1;
                if let Some(j) = t.split_j {
                    let v = if j < x.ncols() { x.get(i, j) } else { 0.0 };
                    if v <= t.split_t {
                        *t.left.entry(lab).or_insert(0.0) += 1.0;
                    } else {
                        *t.right.entry(lab).or_insert(0.0) += 1.0;
                    }
                } else {
                    *t.leaf.entry(lab).or_insert(0.0) += 1.0;
                    if t.n >= 2 {
                        let mut best_j = 0usize;
                        let mut best_r = 0.0;
                        for j in 0..t.lo.len() {
                            let r = t.hi[j] - t.lo[j];
                            if r > best_r {
                                best_r = r;
                                best_j = j;
                            }
                        }
                        if best_r > 1e-12 {
                            let u = self.rng.uniform();
                            t.split_j = Some(best_j);
                            t.split_t = t.lo[best_j] + u * best_r;
                            t.left = t.leaf.clone();
                            t.right = HashMap::new();
                            splits += 1;
                        }
                    }
                }
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(splits as f64);
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n_seen >= 2;
        q.warmup = self.n_seen < 4;
        q.explanation = format!(
            "AMF {} Mondrian stumps, {splits} new splits this batch",
            self.trees.len()
        );
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "Mondrian stump growth",
                "a leaf splits on its widest feature once two labels have been seen",
                format!("n={before}"),
                format!("n={} splits={splits}", self.n_seen),
            ),
        )
    }
}

impl Predict for AmfClassifier {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        if self.trees.is_empty() {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        let out = Vector::from_iter((0..x.nrows()).map(|i| {
            let mut votes = HashMap::<i64, f64>::new();
            for t in &self.trees {
                let lab = if let Some(j) = t.split_j {
                    let v = if j < x.ncols() { x.get(i, j) } else { 0.0 };
                    if v <= t.split_t {
                        amf_majority(&t.left)
                    } else {
                        amf_majority(&t.right)
                    }
                } else {
                    amf_majority(&t.leaf)
                };
                *votes.entry(lab.round() as i64).or_insert(0.0) += 1.0;
            }
            votes
                .iter()
                .max_by(|a, b| {
                    a.1.partial_cmp(b.1)
                        .unwrap_or(std::cmp::Ordering::Equal)
                        .then(b.0.cmp(a.0))
                })
                .map(|(k, _)| *k as f64)
                .unwrap_or(0.0)
        }));
        ctx.finish(out)
    }
}

/// Aggregated Mondrian Forest regressor (river `forest.AMFRegressor`).
///
/// Tree count is not identification `p`.
#[derive(Clone, Debug)]
pub struct AmfRegressor {
    /// Trees.
    pub n_trees: usize,
    trees: Vec<AmfRegTree>,
    n_seen: u64,
    updates: u64,
    rng: Rng,
}

#[derive(Clone, Debug)]
struct AmfRegTree {
    p: usize,
    n: u64,
    lo: Vector,
    hi: Vector,
    split_j: Option<usize>,
    split_t: f64,
    leaf_sum: f64,
    leaf_n: f64,
    left_sum: f64,
    left_n: f64,
    right_sum: f64,
    right_n: f64,
}

impl Default for AmfRegressor {
    fn default() -> Self {
        Self {
            n_trees: 4,
            trees: Vec::new(),
            n_seen: 0,
            updates: 0,
            rng: Rng::new(31),
        }
    }
}

impl AmfRegressor {
    /// AMF regressor with `n_trees` Mondrian stumps.
    pub fn new(n_trees: usize) -> Self {
        Self {
            n_trees: n_trees.max(1),
            ..Self::default()
        }
    }

    fn mean(sum: f64, n: f64) -> f64 {
        if n > 0.0 {
            sum / n
        } else {
            0.0
        }
    }
}

impl PartialFit for AmfRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no labels"),
            );
        };
        if self.trees.is_empty() {
            self.trees = (0..self.n_trees.max(1))
                .map(|_| AmfRegTree {
                    p: x.ncols(),
                    n: 0,
                    lo: Vector::filled(x.ncols(), f64::INFINITY),
                    hi: Vector::filled(x.ncols(), f64::NEG_INFINITY),
                    split_j: None,
                    split_t: 0.0,
                    leaf_sum: 0.0,
                    leaf_n: 0.0,
                    left_sum: 0.0,
                    left_n: 0.0,
                    right_sum: 0.0,
                    right_n: 0.0,
                })
                .collect();
        } else if self.trees[0].p != x.ncols() {
            ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
            return finish_explain(
                ctx,
                reject_explain(
                    self.updates,
                    x.nrows(),
                    self.n_seen,
                    "feature space changed",
                ),
            );
        }
        let before = self.n_seen;
        let mut splits = 0u64;
        for i in 0..x.nrows().min(y.len()) {
            if !y[i].is_finite() {
                continue;
            }
            for t in &mut self.trees {
                for j in 0..x.ncols().min(t.lo.len()) {
                    let v = x.get(i, j);
                    if v < t.lo[j] {
                        t.lo[j] = v;
                    }
                    if v > t.hi[j] {
                        t.hi[j] = v;
                    }
                }
                t.n += 1;
                if let Some(j) = t.split_j {
                    let v = if j < x.ncols() { x.get(i, j) } else { 0.0 };
                    if v <= t.split_t {
                        t.left_sum += y[i];
                        t.left_n += 1.0;
                    } else {
                        t.right_sum += y[i];
                        t.right_n += 1.0;
                    }
                } else {
                    t.leaf_sum += y[i];
                    t.leaf_n += 1.0;
                    if t.n >= 2 {
                        let mut best_j = 0usize;
                        let mut best_r = 0.0;
                        for j in 0..t.lo.len() {
                            let r = t.hi[j] - t.lo[j];
                            if r > best_r {
                                best_r = r;
                                best_j = j;
                            }
                        }
                        if best_r > 1e-12 {
                            let u = self.rng.uniform();
                            t.split_j = Some(best_j);
                            t.split_t = t.lo[best_j] + u * best_r;
                            t.left_sum = t.leaf_sum;
                            t.left_n = t.leaf_n;
                            t.right_sum = 0.0;
                            t.right_n = 0.0;
                            splits += 1;
                        }
                    }
                }
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(splits as f64);
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n_seen >= 2;
        q.warmup = self.n_seen < 4;
        q.explanation = format!(
            "AMFRegressor {} stumps, {splits} new splits this batch",
            self.trees.len()
        );
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "Mondrian stump growth",
                "a leaf splits on its widest feature once two targets have been seen",
                format!("n={before}"),
                format!("n={} splits={splits}", self.n_seen),
            ),
        )
    }
}

impl Predict for AmfRegressor {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        if self.trees.is_empty() {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        let n_trees = self.trees.len().max(1) as f64;
        let out = Vector::from_iter((0..x.nrows()).map(|i| {
            let mut s = 0.0;
            for t in &self.trees {
                let m = if let Some(j) = t.split_j {
                    let v = if j < x.ncols() { x.get(i, j) } else { 0.0 };
                    if v <= t.split_t {
                        Self::mean(t.left_sum, t.left_n)
                    } else {
                        Self::mean(t.right_sum, t.right_n)
                    }
                } else {
                    Self::mean(t.leaf_sum, t.leaf_n)
                };
                s += m;
            }
            s / n_trees
        }));
        ctx.finish(out)
    }
}

/// Shared-density stream clustering (river `cluster.DBSTREAM` lite).
///
/// Micro-cluster count is not identification `p`.
#[derive(Clone, Debug)]
pub struct DbStream {
    /// Merge radius.
    pub eps: f64,
    /// Per-row weight decay.
    pub lambda: f64,
    micros: Vec<(Vector, f64)>,
    n_seen: u64,
    updates: u64,
}

impl Default for DbStream {
    fn default() -> Self {
        Self {
            eps: 1.0,
            lambda: 0.99,
            micros: Vec::new(),
            n_seen: 0,
            updates: 0,
        }
    }
}

impl DbStream {
    /// DBSTREAM with radius `eps`.
    pub fn new(eps: f64) -> Self {
        Self {
            eps,
            ..Self::default()
        }
    }

    /// Current micro-cluster count.
    pub fn n_micro(&self) -> usize {
        self.micros.len()
    }
}

impl PartialFit for DbStream {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let eps = if self.eps.is_finite() && self.eps > 0.0 {
            self.eps
        } else {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message(format!(
                        "DbStream eps={} is not positive; using 1",
                        self.eps
                    ))
                    .build(),
            );
            1.0
        };
        let lam = if self.lambda.is_finite() && self.lambda > 0.0 && self.lambda <= 1.0 {
            self.lambda
        } else {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message(format!(
                        "DbStream lambda={} is not in (0,1]; using 0.99",
                        self.lambda
                    ))
                    .build(),
            );
            0.99
        };
        let before = self.n_seen;
        let mut spawned = 0u64;
        let mut merged = 0u64;
        for i in 0..x.nrows() {
            for mc in self.micros.iter_mut() {
                mc.1 *= lam;
            }
            self.micros.retain(|mc| mc.1 >= 1e-3);
            let row = x.row(i);
            let mut best = None;
            let mut best_d = f64::INFINITY;
            for (c, (ctr, _)) in self.micros.iter().enumerate() {
                let mut d = 0.0;
                for j in 0..row.len().min(ctr.len()) {
                    let z = row[j] - ctr[j];
                    d += z * z;
                }
                d = d.sqrt();
                if d < best_d {
                    best_d = d;
                    best = Some(c);
                }
            }
            if let Some(c) = best {
                if best_d <= eps {
                    let w = self.micros[c].1;
                    let nw = w + 1.0;
                    for j in 0..self.micros[c].0.len().min(row.len()) {
                        let old = self.micros[c].0[j];
                        self.micros[c].0[j] = (old * w + row[j]) / nw;
                    }
                    self.micros[c].1 = nw;
                    merged += 1;
                } else {
                    self.micros.push((row, 1.0));
                    spawned += 1;
                }
            } else {
                self.micros.push((row, 1.0));
                spawned += 1;
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some((spawned + merged) as f64);
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = !self.micros.is_empty();
        q.warmup = self.n_seen < 2;
        q.explanation = format!(
            "DBSTREAM micros={} spawned={spawned} absorbed={merged}",
            self.micros.len()
        );
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "shared-density micro-cluster update",
                "a row joins the nearest micro inside ε or seeds a new centre",
                format!("n={before} micros"),
                format!("n={} micros={}", self.n_seen, self.micros.len()),
            ),
        )
    }
}

impl Predict for DbStream {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        if self.micros.is_empty() {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        let m = self.micros.len();
        let mut parent: Vec<usize> = (0..m).collect();
        let find = |p: &mut [usize], mut a: usize| {
            while p[a] != a {
                p[a] = p[p[a]];
                a = p[a];
            }
            a
        };
        let link = 2.0 * self.eps.max(1e-12);
        for a in 0..m {
            for b in (a + 1)..m {
                let mut d = 0.0;
                for j in 0..self.micros[a].0.len().min(self.micros[b].0.len()) {
                    let z = self.micros[a].0[j] - self.micros[b].0[j];
                    d += z * z;
                }
                if d.sqrt() <= link {
                    let pa = find(&mut parent, a);
                    let pb = find(&mut parent, b);
                    parent[pb] = pa;
                }
            }
        }
        let out = Vector::from_iter((0..x.nrows()).map(|i| {
            let mut best = 0usize;
            let mut bd = f64::INFINITY;
            for (c, (ctr, _)) in self.micros.iter().enumerate() {
                let mut d = 0.0;
                for j in 0..x.ncols().min(ctr.len()) {
                    let z = x.get(i, j) - ctr[j];
                    d += z * z;
                }
                if d < bd {
                    bd = d;
                    best = c;
                }
            }
            let mut a = best;
            while parent[a] != a {
                a = parent[a];
            }
            a as f64
        }));
        ctx.finish(out)
    }
}

/// Poisson-bootstrap bag of RLS members (river `ensemble.BaggingRegressor`).
#[derive(Clone, Debug)]
pub struct OnlineBaggingRegressor {
    /// Members.
    pub n_models: usize,
    models: Vec<LinearRegression>,
    n_seen: u64,
    updates: u64,
    rng: Rng,
}

impl Default for OnlineBaggingRegressor {
    fn default() -> Self {
        Self {
            n_models: 3,
            models: Vec::new(),
            n_seen: 0,
            updates: 0,
            rng: Rng::new(31),
        }
    }
}

impl OnlineBaggingRegressor {
    /// Bag of `n_models` RLS estimators.
    pub fn new(n_models: usize) -> Self {
        Self {
            n_models: n_models.max(1),
            ..Self::default()
        }
    }
}

impl PartialFit for OnlineBaggingRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no labels"),
            );
        };
        if self.models.is_empty() {
            self.models = vec![LinearRegression::new(1.0); self.n_models.max(1)];
        }
        let before = self.n_seen;
        for m in 0..self.models.len() {
            let mut rows: Vec<usize> = Vec::new();
            for i in 0..x.nrows().min(y.len()) {
                let k = self.rng.poisson(1.0) as usize;
                for _ in 0..k {
                    rows.push(i);
                }
            }
            if rows.is_empty() && x.nrows() > 0 {
                rows.push(0);
            }
            if rows.is_empty() {
                continue;
            }
            let xb = Matrix::from_fn(rows.len(), x.ncols(), |r, c| x.get(rows[r], c));
            let yb = Vector::from_iter(rows.iter().map(|&i| y[i]));
            let _ = self.models[m].partial_fit(&xb, Some(&yb), &session.child(format!("bagr_{m}")));
        }
        self.n_seen += x.nrows() as u64;
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some((self.n_seen - before) as f64);
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n_seen >= 2;
        q.warmup = self.n_seen < 4;
        q.explanation = format!(
            "OnlineBaggingRegressor {} RLS members, Poisson bootstrap",
            self.models.len()
        );
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "RLS committee",
                "each member sees a Poisson(1) bootstrap of the batch",
                format!("n={before}"),
                format!("n={}", self.n_seen),
            ),
        )
    }
}

impl Predict for OnlineBaggingRegressor {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        if self.models.is_empty() {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        let mut acc = vec![0.0; x.nrows()];
        let mut k: f64 = 0.0;
        for (t, m) in self.models.iter().enumerate() {
            match m.predict(x, &session.child(format!("br{t}"))) {
                Ok(q) => {
                    for i in 0..x.nrows().min(q.value.len()) {
                        acc[i] += q.value[i];
                    }
                    k += 1.0;
                }
                Err(_) => {}
            }
        }
        let k = k.max(1.0);
        ctx.finish(Vector::from_iter(acc.iter().map(|v| v / k)))
    }
}

/// Streaming binarizer (river `preprocessing.Binarizer`).
#[derive(Clone, Debug)]
pub struct OnlineBinarizer {
    /// Threshold.
    pub threshold: f64,
    p: usize,
    n_seen: u64,
    updates: u64,
}

impl Default for OnlineBinarizer {
    fn default() -> Self {
        Self {
            threshold: 0.0,
            p: 0,
            n_seen: 0,
            updates: 0,
        }
    }
}

impl OnlineBinarizer {
    /// Binarizer with threshold `threshold`.
    pub fn new(threshold: f64) -> Self {
        Self {
            threshold,
            ..Self::default()
        }
    }
}

impl PartialFit for OnlineBinarizer {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.threshold.is_finite() {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message(format!(
                        "OnlineBinarizer threshold={} is not finite; using 0",
                        self.threshold
                    ))
                    .build(),
            );
            self.threshold = 0.0;
        }
        if self.p == 0 {
            self.p = x.ncols();
        } else if self.p != x.ncols() {
            ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
            return finish_explain(
                ctx,
                reject_explain(
                    self.updates,
                    x.nrows(),
                    self.n_seen,
                    "feature space changed",
                ),
            );
        }
        let before = self.n_seen;
        self.n_seen += x.nrows() as u64;
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(0.0);
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = true;
        q.warmup = false;
        q.explanation = format!("OnlineBinarizer threshold={:.6e}", self.threshold);
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "threshold map",
                "each coordinate is 1 iff it meets the recorded cut",
                format!("n={before}"),
                format!("n={}", self.n_seen),
            ),
        )
    }
}

impl Transform for OnlineBinarizer {
    fn transform(&self, x: &Matrix, session: &Session) -> Result<Qualified<Matrix>> {
        let mut ctx = FitCtx::with_session(session.child("transform"));
        inspect_online_xy(&mut ctx, x, None);
        let t = if self.threshold.is_finite() {
            self.threshold
        } else {
            0.0
        };
        ctx.finish(Matrix::from_fn(x.nrows(), x.ncols(), |i, j| {
            if x.get(i, j) >= t {
                1.0
            } else {
                0.0
            }
        }))
    }
}

/// Streaming isolation forest (river `anomaly.HalfSpaceTrees` / isolation forest).
///
/// Tree count is not identification `p`.
#[derive(Clone, Debug)]
pub struct OnlineIsolationForest {
    /// Trees.
    pub n_trees: usize,
    /// Depth.
    pub max_depth: usize,
    trees: Vec<Vec<(usize, f64)>>,
    masses: Vec<HashMap<u32, u64>>,
    mins: Vector,
    maxs: Vector,
    n_seen: u64,
    updates: u64,
    initialized: bool,
    rng: Rng,
}

impl Default for OnlineIsolationForest {
    fn default() -> Self {
        Self {
            n_trees: 4,
            max_depth: 4,
            trees: Vec::new(),
            masses: Vec::new(),
            mins: Vector::zeros(0),
            maxs: Vector::zeros(0),
            n_seen: 0,
            updates: 0,
            initialized: false,
            rng: Rng::new(19),
        }
    }
}

impl OnlineIsolationForest {
    /// Isolation ensemble with `n_trees` trees of depth `max_depth`.
    pub fn new(n_trees: usize, max_depth: usize) -> Self {
        Self {
            n_trees: n_trees.max(1),
            max_depth: max_depth.max(1),
            ..Self::default()
        }
    }

    fn grow(&mut self, p: usize) {
        self.trees.clear();
        self.masses.clear();
        for _ in 0..self.n_trees.max(1) {
            let mut cuts = Vec::new();
            for _ in 0..self.max_depth.max(1) {
                let j = if p == 0 { 0 } else { self.rng.below(p) };
                let lo = if j < self.mins.len() {
                    self.mins[j]
                } else {
                    0.0
                };
                let hi = if j < self.maxs.len() {
                    self.maxs[j]
                } else {
                    1.0
                };
                let thr = if hi > lo {
                    self.rng.uniform_range(lo, hi)
                } else {
                    lo
                };
                cuts.push((j, thr));
            }
            self.trees.push(cuts);
            self.masses.push(HashMap::new());
        }
    }

    fn path_key(cuts: &[(usize, f64)], x: &Matrix, i: usize) -> (u32, usize) {
        let mut key: u32 = 0;
        let mut depth = 0usize;
        for (bit, (j, thr)) in cuts.iter().enumerate() {
            let v = if *j < x.ncols() { x.get(i, *j) } else { 0.0 };
            if v > *thr {
                key |= 1 << bit;
            }
            depth = bit + 1;
        }
        (key, depth)
    }

    /// Mean isolation score in \([0, 1]\); higher is more anomalous.
    pub fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        if self.trees.is_empty() || self.n_seen == 0 {
            return 0.5;
        }
        let mut s = 0.0;
        for (cuts, mass) in self.trees.iter().zip(&self.masses) {
            let (key, depth) = Self::path_key(cuts, x, i);
            let m = *mass.get(&key).unwrap_or(&0);
            let c = (self.n_seen as f64).ln().max(1.0);
            let path = depth as f64 + if m > 1 { (m as f64).ln() } else { 0.0 };
            s += 2.0_f64.powf(-path / c);
        }
        s / self.trees.len() as f64
    }
}

impl PartialFit for OnlineIsolationForest {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.initialized {
            self.mins = Vector::from_iter((0..x.ncols()).map(|j| {
                (0..x.nrows())
                    .map(|i| x.get(i, j))
                    .fold(f64::INFINITY, f64::min)
            }));
            self.maxs = Vector::from_iter((0..x.ncols()).map(|j| {
                (0..x.nrows())
                    .map(|i| x.get(i, j))
                    .fold(f64::NEG_INFINITY, f64::max)
            }));
            self.grow(x.ncols());
            self.initialized = true;
        } else if self.mins.len() != x.ncols() {
            ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
            return finish_explain(
                ctx,
                reject_explain(
                    self.updates,
                    x.nrows(),
                    self.n_seen,
                    "feature space changed",
                ),
            );
        }
        let before = self.n_seen;
        for i in 0..x.nrows() {
            for (cuts, mass) in self.trees.iter().zip(self.masses.iter_mut()) {
                let (key, _) = Self::path_key(cuts, x, i);
                *mass.entry(key).or_insert(0) += 1;
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let after = if x.nrows() > 0 {
            self.score_row(x, 0)
        } else {
            0.5
        };
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(0.0);
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n_seen >= 4;
        q.warmup = self.n_seen < 4;
        q.explanation = format!("OnlineIsolationForest score={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "random-cut isolation counts",
                "each tree records the leaf mass of the hashed path",
                format!("n={before}"),
                format!("n={} score={after:.6e}", self.n_seen),
            ),
        )
    }
}

impl Predict for OnlineIsolationForest {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        inspect_online_xy(&mut ctx, x, None);
        ctx.finish(Vector::from_iter(
            (0..x.nrows()).map(|i| self.score_row(x, i)),
        ))
    }
}

fn rolling_push(window: &mut Vec<f64>, v: f64, cap: usize) {
    if !v.is_finite() {
        return;
    }
    window.push(v);
    if window.len() > cap {
        window.remove(0);
    }
}

/// Rolling minimum (river `stats.RollingMin`).
#[derive(Clone, Debug, Default)]
pub struct RollingMin {
    window: Vec<f64>,
    n_seen: u64,
    updates: u64,
}

impl RollingMin {
    /// Empty rolling min.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current min, or NaN when empty.
    pub fn score(&self) -> f64 {
        self.window
            .iter()
            .copied()
            .fold(f64::NAN, |a, b| if a.is_nan() { b } else { a.min(b) })
    }
}

impl PartialFit for RollingMin {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let before = self.score();
        for i in 0..x.nrows() {
            rolling_push(&mut self.window, x.get(i, 0), 256);
            if x.get(i, 0).is_finite() {
                self.n_seen += 1;
            }
        }
        self.updates += 1;
        let after = self.score();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.window.len() as f64;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = !self.window.is_empty();
        q.warmup = self.window.is_empty();
        q.explanation = format!("RollingMin={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "windowed minimum",
                "256-row sliding min of column 0",
                format!("min={before:.6e}"),
                format!("min={after:.6e}"),
            ),
        )
    }
}

/// Rolling maximum (river `stats.RollingMax`).
#[derive(Clone, Debug, Default)]
pub struct RollingMax {
    window: Vec<f64>,
    n_seen: u64,
    updates: u64,
}

impl RollingMax {
    /// Empty rolling max.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current max, or NaN when empty.
    pub fn score(&self) -> f64 {
        self.window
            .iter()
            .copied()
            .fold(f64::NAN, |a, b| if a.is_nan() { b } else { a.max(b) })
    }
}

impl PartialFit for RollingMax {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let before = self.score();
        for i in 0..x.nrows() {
            rolling_push(&mut self.window, x.get(i, 0), 256);
            if x.get(i, 0).is_finite() {
                self.n_seen += 1;
            }
        }
        self.updates += 1;
        let after = self.score();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.window.len() as f64;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = !self.window.is_empty();
        q.warmup = self.window.is_empty();
        q.explanation = format!("RollingMax={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "windowed maximum",
                "256-row sliding max of column 0",
                format!("max={before:.6e}"),
                format!("max={after:.6e}"),
            ),
        )
    }
}

/// Streaming skewness (river `stats.Skew`).
#[derive(Clone, Debug, Default)]
pub struct OnlineSkew {
    n: f64,
    mean: f64,
    m2: f64,
    m3: f64,
    updates: u64,
}

impl OnlineSkew {
    /// Empty skewness accumulator.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current skewness, or NaN during warmup.
    pub fn score(&self) -> f64 {
        if self.n < 3.0 || self.m2 <= 1e-18 {
            f64::NAN
        } else {
            self.n.sqrt() * self.m3 / self.m2.powf(1.5)
        }
    }
}

impl PartialFit for OnlineSkew {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let before = self.score();
        for i in 0..x.nrows() {
            let v = x.get(i, 0);
            if !v.is_finite() {
                continue;
            }
            self.n += 1.0;
            let n1 = self.n - 1.0;
            let delta = v - self.mean;
            let delta_n = delta / self.n;
            let term1 = delta * delta_n * n1;
            self.mean += delta_n;
            self.m3 += term1 * delta_n * (self.n - 2.0) - 3.0 * delta_n * self.m2;
            self.m2 += term1;
        }
        self.updates += 1;
        let after = self.score();
        let mut q =
            IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n as u64);
        q.effective_sample_size = self.n;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n >= 3.0;
        q.warmup = self.n < 3.0;
        q.explanation = format!("OnlineSkew={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "Welford third moment",
                "skewness from central moments of column 0",
                format!("skew={before:.6e}"),
                format!("skew={after:.6e}"),
            ),
        )
    }
}

/// Streaming excess kurtosis (river `stats.Kurtosis`).
#[derive(Clone, Debug, Default)]
pub struct OnlineKurtosis {
    n: f64,
    mean: f64,
    m2: f64,
    m3: f64,
    m4: f64,
    updates: u64,
}

impl OnlineKurtosis {
    /// Empty kurtosis accumulator.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current excess kurtosis, or NaN during warmup.
    pub fn score(&self) -> f64 {
        if self.n < 4.0 || self.m2 <= 1e-18 {
            f64::NAN
        } else {
            self.n * self.m4 / (self.m2 * self.m2) - 3.0
        }
    }
}

impl PartialFit for OnlineKurtosis {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let before = self.score();
        for i in 0..x.nrows() {
            let v = x.get(i, 0);
            if !v.is_finite() {
                continue;
            }
            self.n += 1.0;
            let n1 = self.n - 1.0;
            let delta = v - self.mean;
            let delta_n = delta / self.n;
            let delta_n2 = delta_n * delta_n;
            let term1 = delta * delta_n * n1;
            self.mean += delta_n;
            self.m4 += term1 * delta_n2 * (self.n * self.n - 3.0 * self.n + 3.0)
                + 6.0 * delta_n2 * self.m2
                - 4.0 * delta_n * self.m3;
            self.m3 += term1 * delta_n * (self.n - 2.0) - 3.0 * delta_n * self.m2;
            self.m2 += term1;
        }
        self.updates += 1;
        let after = self.score();
        let mut q =
            IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n as u64);
        q.effective_sample_size = self.n;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n >= 4.0;
        q.warmup = self.n < 4.0;
        q.explanation = format!("OnlineKurtosis={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "Welford fourth moment",
                "excess kurtosis from central moments of column 0",
                format!("kurt={before:.6e}"),
                format!("kurt={after:.6e}"),
            ),
        )
    }
}

/// Streaming Shannon entropy of rounded values (river `stats.Entropy`).
#[derive(Clone, Debug, Default)]
pub struct OnlineEntropy {
    counts: HashMap<i64, u64>,
    n: u64,
    updates: u64,
}

impl OnlineEntropy {
    /// Empty entropy accumulator.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current entropy in nats, or NaN when empty.
    pub fn score(&self) -> f64 {
        if self.n == 0 {
            return f64::NAN;
        }
        let tot = self.n as f64;
        let mut h = 0.0;
        for c in self.counts.values() {
            let p = *c as f64 / tot;
            if p > 0.0 {
                h -= p * p.ln();
            }
        }
        h
    }
}

impl PartialFit for OnlineEntropy {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let before = self.score();
        for i in 0..x.nrows() {
            let v = x.get(i, 0);
            if !v.is_finite() {
                continue;
            }
            let key = v.round() as i64;
            *self.counts.entry(key).or_insert(0) += 1;
            self.n += 1;
        }
        self.updates += 1;
        let after = self.score();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n);
        q.effective_sample_size = self.n as f64;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.counts.len() >= 2;
        q.warmup = self.n < 2;
        q.explanation = format!("OnlineEntropy={after:.6e} bins={}", self.counts.len());
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "histogram entropy",
                "Shannon entropy of rounded column-0 values",
                format!("H={before:.6e}"),
                format!("H={after:.6e}"),
            ),
        )
    }
}

/// Periodic sine/cosine map (river-style calendar / Fourier features).
///
/// Period is not identification `p`.
#[derive(Clone, Debug)]
pub struct Periodic {
    /// Period of the cycle.
    pub period: f64,
    p: usize,
    n_seen: u64,
    updates: u64,
}

impl Default for Periodic {
    fn default() -> Self {
        Self {
            period: 12.0,
            p: 0,
            n_seen: 0,
            updates: 0,
        }
    }
}

impl Periodic {
    /// Periodic map with period `period`.
    pub fn new(period: f64) -> Self {
        Self {
            period,
            ..Self::default()
        }
    }
}

impl PartialFit for Periodic {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.period.is_finite() || self.period <= 0.0 {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message(format!(
                        "Periodic.period={} is not positive; using 1",
                        self.period
                    ))
                    .build(),
            );
            self.period = 1.0;
        }
        if self.p == 0 {
            self.p = x.ncols();
        } else if self.p != x.ncols() {
            ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
            return finish_explain(
                ctx,
                reject_explain(
                    self.updates,
                    x.nrows(),
                    self.n_seen,
                    "feature space changed",
                ),
            );
        }
        let before = self.n_seen;
        self.n_seen += x.nrows() as u64;
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(0.0);
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = true;
        q.warmup = false;
        q.explanation = format!("Periodic period={:.6e}", self.period);
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "sin/cos period map",
                "each column becomes a 2-d Fourier pair",
                format!("n={before}"),
                format!("n={}", self.n_seen),
            ),
        )
    }
}

impl Transform for Periodic {
    fn transform(&self, x: &Matrix, session: &Session) -> Result<Qualified<Matrix>> {
        let mut ctx = FitCtx::with_session(session.child("transform"));
        inspect_online_xy(&mut ctx, x, None);
        let per = if self.period.is_finite() && self.period > 0.0 {
            self.period
        } else {
            1.0
        };
        let tau = std::f64::consts::TAU;
        ctx.finish(Matrix::from_fn(x.nrows(), x.ncols() * 2, |i, j| {
            let col = j / 2;
            let v = x.get(i, col);
            let ang = tau * v / per;
            if j % 2 == 0 {
                ang.sin()
            } else {
                ang.cos()
            }
        }))
    }
}

/// Streaming pairwise covariance (river `stats.Cov`).
#[derive(Clone, Debug, Default)]
pub struct OnlineCovariance {
    n: f64,
    mx: f64,
    my: f64,
    c: f64,
    updates: u64,
}

impl OnlineCovariance {
    /// Empty covariance accumulator.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current covariance, or NaN during warmup.
    pub fn score(&self) -> f64 {
        if self.n < 2.0 {
            f64::NAN
        } else {
            self.c / (self.n - 1.0)
        }
    }
}

impl PartialFit for OnlineCovariance {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        if x.ncols() < 2 && y.is_none() {
            ctx.push(
                Issue::builder(IssueCode::InsufficientSample)
                    .severity(Severity::Warning)
                    .message("OnlineCovariance needs two columns or an explicit y")
                    .build(),
            );
        }
        let before = self.score();
        for i in 0..x.nrows() {
            let a = x.get(i, 0);
            let b = if x.ncols() >= 2 {
                x.get(i, 1)
            } else if let Some(y) = y {
                if i < y.len() {
                    y[i]
                } else {
                    f64::NAN
                }
            } else {
                f64::NAN
            };
            if !a.is_finite() || !b.is_finite() {
                continue;
            }
            self.n += 1.0;
            let dx = a - self.mx;
            self.mx += dx / self.n;
            self.my += (b - self.my) / self.n;
            self.c += dx * (b - self.my);
        }
        self.updates += 1;
        let after = self.score();
        let mut q =
            IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n as u64);
        q.effective_sample_size = self.n;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n >= 2.0;
        q.warmup = self.n < 2.0;
        q.explanation = format!("OnlineCovariance={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "Welford covariance",
                "pairwise covariance of column 0 with column 1 or y",
                format!("cov={before:.6e}"),
                format!("cov={after:.6e}"),
            ),
        )
    }
}

/// Hashing trick (river `preprocessing.FeatureHasher` / sklearn `FeatureHasher`).
///
/// Output width is not identification `p`.
#[derive(Clone, Debug)]
pub struct HashingTrick {
    /// Hash-bin count.
    pub n_features: usize,
    n_seen: u64,
    updates: u64,
}

impl Default for HashingTrick {
    fn default() -> Self {
        Self {
            n_features: 8,
            n_seen: 0,
            updates: 0,
        }
    }
}

impl HashingTrick {
    /// Hasher with `n_features` bins.
    pub fn new(n_features: usize) -> Self {
        Self {
            n_features: n_features.max(1),
            ..Self::default()
        }
    }

    fn bin(j: usize, n: usize) -> (usize, f64) {
        let h = (j as u64).wrapping_mul(0x9E37_79B9_7F4A_7C15);
        let sign = if (h >> 1) & 1 == 0 { 1.0 } else { -1.0 };
        ((h as usize) % n.max(1), sign)
    }
}

impl PartialFit for HashingTrick {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        if self.n_features == 0 {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message("HashingTrick n_features=0; using 1")
                    .build(),
            );
            self.n_features = 1;
        }
        let before = self.n_seen;
        self.n_seen += x.nrows() as u64;
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(0.0);
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = true;
        q.warmup = false;
        q.explanation = format!("HashingTrick bins={}", self.n_features);
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "signed hash projection",
                "each input column is folded into a fixed bag of bins",
                format!("n={before}"),
                format!("n={}", self.n_seen),
            ),
        )
    }
}

impl Transform for HashingTrick {
    fn transform(&self, x: &Matrix, session: &Session) -> Result<Qualified<Matrix>> {
        let mut ctx = FitCtx::with_session(session.child("transform"));
        inspect_online_xy(&mut ctx, x, None);
        let m = self.n_features.max(1);
        let mut out = Matrix::zeros(x.nrows(), m);
        for i in 0..x.nrows() {
            for j in 0..x.ncols() {
                let (b, s) = Self::bin(j, m);
                out.set(i, b, out.get(i, b) + s * x.get(i, j));
            }
        }
        ctx.finish(out)
    }
}

/// Hashed bag-of-values (river `feature_extraction.BagOfWords`).
///
/// Finite entries of `X` are hashed into `n_features` count bins.
/// Bin count is not identification `p`.
#[derive(Clone, Debug)]
pub struct BagOfWords {
    /// Hash-bin count.
    pub n_features: usize,
    n_seen: u64,
    updates: u64,
}

impl Default for BagOfWords {
    fn default() -> Self {
        Self {
            n_features: 8,
            n_seen: 0,
            updates: 0,
        }
    }
}

impl BagOfWords {
    /// Bag with `n_features` bins.
    pub fn new(n_features: usize) -> Self {
        Self {
            n_features: n_features.max(1),
            ..Self::default()
        }
    }

    fn bin(bits: u64, col: usize, n: usize) -> usize {
        let h = bits
            .wrapping_mul(0x9E37_79B9_7F4A_7C15)
            .wrapping_add((col as u64).wrapping_mul(0xC2B2_AE3D_27D4_EB4F));
        (h as usize) % n.max(1)
    }
}

impl PartialFit for BagOfWords {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        if self.n_features == 0 {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message("BagOfWords n_features=0; using 1")
                    .build(),
            );
            self.n_features = 1;
        }
        let before = self.n_seen;
        self.n_seen += x.nrows() as u64;
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(0.0);
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = true;
        q.warmup = false;
        q.explanation = format!("BagOfWords bins={}", self.n_features);
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "hashed bag-of-values",
                "each finite entry is folded into a fixed count bag",
                format!("n={before}"),
                format!("n={}", self.n_seen),
            ),
        )
    }
}

impl Transform for BagOfWords {
    fn transform(&self, x: &Matrix, session: &Session) -> Result<Qualified<Matrix>> {
        let mut ctx = FitCtx::with_session(session.child("transform"));
        inspect_online_xy(&mut ctx, x, None);
        let m = self.n_features.max(1);
        let mut out = Matrix::zeros(x.nrows(), m);
        for i in 0..x.nrows() {
            for j in 0..x.ncols() {
                let v = x.get(i, j);
                if !v.is_finite() {
                    continue;
                }
                let b = Self::bin(v.to_bits(), j, m);
                out.set(i, b, out.get(i, b) + 1.0);
            }
        }
        ctx.finish(out)
    }
}

/// Stochastic gradient tree classifier (river `tree.SGTClassifier`).
///
/// Lite: a single logit leaf updated by log-loss SGD. Split / leaf counts
/// are not identification `p`.
#[derive(Clone, Debug)]
pub struct SgtClassifier {
    /// Step size.
    pub learning_rate: f64,
    logit: f64,
    n_seen: u64,
    updates: u64,
}

impl Default for SgtClassifier {
    fn default() -> Self {
        Self {
            learning_rate: 0.1,
            logit: 0.0,
            n_seen: 0,
            updates: 0,
        }
    }
}

impl SgtClassifier {
    /// Default SGT classifier.
    pub fn new() -> Self {
        Self::default()
    }
}

impl PartialFit for SgtClassifier {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "SGT needs labels"),
            );
        };
        let before = self.logit;
        let lr = if self.learning_rate.is_finite() && self.learning_rate > 0.0 {
            self.learning_rate
        } else {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message("SgtClassifier learning_rate is not a positive finite; using 0.1")
                    .build(),
            );
            0.1
        };
        let mut loss_before = 0.0_f64;
        let mut loss_after = 0.0_f64;
        for i in 0..x.nrows().min(y.len()) {
            if !y[i].is_finite() {
                continue;
            }
            let yi = if y[i] >= 0.5 { 1.0 } else { 0.0 };
            let p0 = 1.0 / (1.0 + (-self.logit).exp());
            loss_before += -(yi * p0.max(1e-15).ln() + (1.0 - yi) * (1.0 - p0).max(1e-15).ln());
            self.logit -= lr * (p0 - yi);
            let p1 = 1.0 / (1.0 + (-self.logit).exp());
            loss_after += -(yi * p1.max(1e-15).ln() + (1.0 - yi) * (1.0 - p1).max(1e-15).ln());
            self.n_seen += 1;
        }
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some((self.logit - before).abs());
        q.information_gain = Some((loss_before - loss_after).abs());
        q.loss_before = Some(loss_before);
        q.loss_after = Some(loss_after);
        q.still_identified = self.n_seen >= 2;
        q.warmup = self.n_seen < 5;
        q.explanation = format!("SgtClassifier logit {:.6e} → {:.6e}", before, self.logit);
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "SGT leaf logit",
                "log-loss SGD on a single stochastic-gradient tree leaf",
                format!("logit={before:.6e}"),
                format!("logit={:.6e}", self.logit),
            ),
        )
    }
}

/// Stochastic gradient tree regressor (river `tree.SGTRegressor`).
///
/// Lite: a single leaf mean updated by squared-error SGD. Leaf count is not
/// identification `p`.
#[derive(Clone, Debug)]
pub struct SgtRegressor {
    /// Step size.
    pub learning_rate: f64,
    level: f64,
    n_seen: u64,
    updates: u64,
}

impl Default for SgtRegressor {
    fn default() -> Self {
        Self {
            learning_rate: 0.1,
            level: 0.0,
            n_seen: 0,
            updates: 0,
        }
    }
}

impl SgtRegressor {
    /// Default SGT regressor.
    pub fn new() -> Self {
        Self::default()
    }
}

impl PartialFit for SgtRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "SGT needs y"),
            );
        };
        let before = self.level;
        let lr = if self.learning_rate.is_finite() && self.learning_rate > 0.0 {
            self.learning_rate
        } else {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message("SgtRegressor learning_rate is not a positive finite; using 0.1")
                    .build(),
            );
            0.1
        };
        let mut loss_before = 0.0_f64;
        let mut loss_after = 0.0_f64;
        for i in 0..x.nrows().min(y.len()) {
            if !y[i].is_finite() {
                continue;
            }
            let e0 = self.level - y[i];
            loss_before += e0 * e0;
            self.level -= lr * e0;
            let e1 = self.level - y[i];
            loss_after += e1 * e1;
            self.n_seen += 1;
        }
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some((self.level - before).abs());
        q.information_gain = Some((loss_before - loss_after).abs());
        q.loss_before = Some(loss_before);
        q.loss_after = Some(loss_after);
        q.still_identified = self.n_seen >= 2;
        q.warmup = self.n_seen < 5;
        q.explanation = format!("SgtRegressor level {:.6e} → {:.6e}", before, self.level);
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "SGT leaf level",
                "squared-error SGD on a single stochastic-gradient tree leaf",
                format!("level={before:.6e}"),
                format!("level={:.6e}", self.level),
            ),
        )
    }
}

/// Incremental multi-output Hoeffding-style tree (river `iSOUPTreeRegressor`).
///
/// Output 0 is `y`. Extra `X` columns beyond the first are additional targets.
/// Output count is not identification `p`.
#[derive(Clone, Debug)]
pub struct IsoUPTree {
    /// Number of output heads.
    pub n_outputs: usize,
    means: Vec<f64>,
    counts: Vec<f64>,
    n_seen: u64,
    updates: u64,
}

impl Default for IsoUPTree {
    fn default() -> Self {
        Self {
            n_outputs: 2,
            means: vec![0.0; 2],
            counts: vec![0.0; 2],
            n_seen: 0,
            updates: 0,
        }
    }
}

impl IsoUPTree {
    /// `n_outputs` target heads.
    pub fn new(n_outputs: usize) -> Self {
        let k = n_outputs.max(1);
        Self {
            n_outputs: k,
            means: vec![0.0; k],
            counts: vec![0.0; k],
            n_seen: 0,
            updates: 0,
        }
    }
}

impl PartialFit for IsoUPTree {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "iSOUP needs y"),
            );
        };
        if self.n_outputs > 1 && x.ncols() < 2 {
            ctx.push(
                Issue::builder(IssueCode::DimensionMismatch)
                    .severity(Severity::Warning)
                    .message("IsoUPTree extra outputs have no extra X columns; only y is updated")
                    .build(),
            );
        }
        if self.means.len() != self.n_outputs.max(1) {
            self.means.resize(self.n_outputs.max(1), 0.0);
            self.counts.resize(self.n_outputs.max(1), 0.0);
        }
        let before = self.means.clone();
        for i in 0..x.nrows().min(y.len()) {
            if y[i].is_finite() {
                let c = self.counts[0] + 1.0;
                self.means[0] += (y[i] - self.means[0]) / c;
                self.counts[0] = c;
            }
            for o in 1..self.n_outputs.min(self.means.len()) {
                if o < x.ncols() {
                    let v = x.get(i, o);
                    if v.is_finite() {
                        let c = self.counts[o] + 1.0;
                        self.means[o] += (v - self.means[o]) / c;
                        self.counts[o] = c;
                    }
                }
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let mut dsum = 0.0_f64;
        for (a, b) in before.iter().zip(self.means.iter()) {
            dsum += (b - a).abs();
        }
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(dsum);
        q.information_gain = Some(dsum);
        q.still_identified = self.counts.iter().all(|&c| c > 0.0);
        q.warmup = self.counts.iter().any(|&c| c < 2.0);
        q.explanation = format!("IsoUPTree means={:?}", self.means);
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "iSOUP per-output leaf means",
                "incremental multi-target means; extra X columns are additional targets",
                format!("means={before:?}"),
                format!("means={:?}", self.means),
            ),
        )
    }
}

/// Pegasos hinge SVM (online linear SVM; river / SGD hinge peer).
///
/// Feature count is not treated as an extra identification `p` on a stream.
#[derive(Clone, Debug)]
pub struct OnlineSvm {
    /// Regularization \(\lambda > 0\).
    pub lambda: f64,
    coef: Vector,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for OnlineSvm {
    fn default() -> Self {
        Self {
            lambda: 1e-3,
            coef: Vector::zeros(0),
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl OnlineSvm {
    /// Default Pegasos SVM.
    pub fn new() -> Self {
        Self::default()
    }
}

impl PartialFit for OnlineSvm {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(
                    self.updates,
                    x.nrows(),
                    self.n_seen,
                    "OnlineSvm needs labels",
                ),
            );
        };
        if !self.initialized {
            self.coef = Vector::zeros(x.ncols());
            self.initialized = true;
        } else if self.coef.len() != x.ncols() {
            ctx.push(
                Issue::builder(IssueCode::FeatureSpaceChangedOnline)
                    .severity(Severity::Warning)
                    .message("OnlineSvm feature count changed")
                    .build(),
            );
            self.coef = Vector::zeros(x.ncols());
        }
        let mut lam = self.lambda;
        if !lam.is_finite() || lam <= 0.0 {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message(format!(
                        "OnlineSvm λ={lam} is not a positive finite; using 1e-3"
                    ))
                    .build(),
            );
            lam = 1e-3;
            self.lambda = lam;
        }
        let before = self.coef.clone();
        let mut loss_before = 0.0_f64;
        let mut loss_after = 0.0_f64;
        for i in 0..x.nrows().min(y.len()) {
            if !y[i].is_finite() {
                continue;
            }
            let yi = if y[i] >= 0.5 { 1.0 } else { -1.0 };
            let mut pred = 0.0_f64;
            for j in 0..x.ncols() {
                pred += self.coef[j] * x.get(i, j);
            }
            loss_before += (1.0 - yi * pred).max(0.0);
            self.n_seen += 1;
            let eta = 1.0 / (lam * self.n_seen as f64);
            let decay = (1.0 - eta * lam).max(0.0);
            for j in 0..x.ncols() {
                self.coef[j] *= decay;
            }
            if yi * pred < 1.0 {
                for j in 0..x.ncols() {
                    self.coef[j] += eta * yi * x.get(i, j);
                }
            }
            let mut pred1 = 0.0_f64;
            for j in 0..x.ncols() {
                pred1 += self.coef[j] * x.get(i, j);
            }
            loss_after += (1.0 - yi * pred1).max(0.0);
        }
        self.updates += 1;
        let delta = self.coef.sub(&before);
        let expl = pack_linear_explain(
            &mut ctx,
            self.updates,
            x.nrows(),
            self.n_seen,
            &delta,
            loss_before,
            loss_after,
            self.n_seen as usize > x.ncols(),
            self.n_seen < 5,
            "Pegasos hinge weights",
            "online SVM: decay toward the regularizer, then a hinge subgradient step",
        );
        finish_explain(ctx, expl)
    }
}

/// Streaming median absolute deviation (river `stats.MAD`).
#[derive(Clone, Debug, Default)]
pub struct OnlineMad {
    window: Vec<f64>,
    n_seen: u64,
    updates: u64,
}

impl OnlineMad {
    /// Empty MAD accumulator.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current MAD, or NaN when empty.
    pub fn score(&self) -> f64 {
        if self.window.is_empty() {
            return f64::NAN;
        }
        let mut xs = self.window.clone();
        xs.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let mid = xs[xs.len() / 2];
        let mut dev: Vec<f64> = xs.iter().map(|v| (v - mid).abs()).collect();
        dev.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        dev[dev.len() / 2]
    }
}

impl PartialFit for OnlineMad {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let before = self.score();
        for i in 0..x.nrows() {
            rolling_push(&mut self.window, x.get(i, 0), 256);
            if x.get(i, 0).is_finite() {
                self.n_seen += 1;
            }
        }
        self.updates += 1;
        let after = self.score();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.window.len() as f64;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.window.len() >= 3;
        q.warmup = self.window.len() < 3;
        q.explanation = format!("OnlineMad={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "windowed MAD",
                "median absolute deviation of column 0",
                format!("mad={before:.6e}"),
                format!("mad={after:.6e}"),
            ),
        )
    }
}

/// Streaming interquartile range (river `stats.IQR`).
#[derive(Clone, Debug, Default)]
pub struct OnlineIqr {
    window: Vec<f64>,
    n_seen: u64,
    updates: u64,
}

impl OnlineIqr {
    /// Empty IQR accumulator.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current IQR, or NaN when empty.
    pub fn score(&self) -> f64 {
        if self.window.len() < 2 {
            return f64::NAN;
        }
        let mut xs = self.window.clone();
        xs.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let q = |t: f64| {
            let u = t * (xs.len() - 1) as f64;
            let lo = u.floor() as usize;
            let hi = u.ceil() as usize;
            let w = u - lo as f64;
            (1.0 - w) * xs[lo] + w * xs[hi.min(xs.len() - 1)]
        };
        q(0.75) - q(0.25)
    }
}

impl PartialFit for OnlineIqr {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let before = self.score();
        for i in 0..x.nrows() {
            rolling_push(&mut self.window, x.get(i, 0), 256);
            if x.get(i, 0).is_finite() {
                self.n_seen += 1;
            }
        }
        self.updates += 1;
        let after = self.score();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.window.len() as f64;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.window.len() >= 4;
        q.warmup = self.window.len() < 4;
        q.explanation = format!("OnlineIqr={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "windowed IQR",
                "p75 − p25 of column 0",
                format!("iqr={before:.6e}"),
                format!("iqr={after:.6e}"),
            ),
        )
    }
}

/// Streaming Pearson correlation (river `stats.PearsonCorr`).
#[derive(Clone, Debug, Default)]
pub struct OnlinePearson {
    n: f64,
    mx: f64,
    my: f64,
    c: f64,
    vx: f64,
    vy: f64,
    updates: u64,
}

impl OnlinePearson {
    /// Empty correlation accumulator.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current correlation, or NaN during warmup.
    pub fn score(&self) -> f64 {
        if self.n < 2.0 {
            return f64::NAN;
        }
        let den = (self.vx * self.vy).sqrt();
        if den <= 1e-18 {
            f64::NAN
        } else {
            self.c / den
        }
    }
}

impl PartialFit for OnlinePearson {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        if x.ncols() < 2 && y.is_none() {
            ctx.push(
                Issue::builder(IssueCode::InsufficientSample)
                    .severity(Severity::Warning)
                    .message("OnlinePearson needs two columns or an explicit y")
                    .build(),
            );
        }
        let before = self.score();
        for i in 0..x.nrows() {
            let a = x.get(i, 0);
            let b = if x.ncols() >= 2 {
                x.get(i, 1)
            } else if let Some(y) = y {
                if i < y.len() {
                    y[i]
                } else {
                    f64::NAN
                }
            } else {
                f64::NAN
            };
            if !a.is_finite() || !b.is_finite() {
                continue;
            }
            self.n += 1.0;
            let dx = a - self.mx;
            self.mx += dx / self.n;
            let dy = b - self.my;
            self.my += dy / self.n;
            self.c += dx * (b - self.my);
            self.vx += dx * (a - self.mx);
            self.vy += dy * (b - self.my);
        }
        self.updates += 1;
        let after = self.score();
        let mut q =
            IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n as u64);
        q.effective_sample_size = self.n;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n >= 3.0;
        q.warmup = self.n < 3.0;
        q.explanation = format!("OnlinePearson={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "Welford correlation",
                "Pearson r of column 0 with column 1 or y",
                format!("r={before:.6e}"),
                format!("r={after:.6e}"),
            ),
        )
    }
}

/// Streaming mode of a discretized column (river `stats.Mode`).
#[derive(Clone, Debug, Default)]
pub struct OnlineMode {
    counts: HashMap<i64, u64>,
    mode_key: i64,
    mode_count: u64,
    n_seen: u64,
    updates: u64,
}

impl OnlineMode {
    /// Empty mode accumulator.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current mode (decoded from milli-bins), or NaN before the first update.
    pub fn score(&self) -> f64 {
        if self.n_seen == 0 {
            f64::NAN
        } else {
            self.mode_key as f64 / 1000.0
        }
    }
}

impl PartialFit for OnlineMode {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let before = self.score();
        for i in 0..x.nrows() {
            let v = x.get(i, 0);
            if !v.is_finite() {
                continue;
            }
            let key = (v * 1000.0).round() as i64;
            let c = self.counts.entry(key).or_insert(0);
            *c += 1;
            let cnt = *c;
            if cnt > self.mode_count || (cnt == self.mode_count && key < self.mode_key) {
                self.mode_count = cnt;
                self.mode_key = key;
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let after = self.score();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n_seen >= 1;
        q.warmup = self.n_seen < 1;
        q.explanation = format!("OnlineMode={after:.6e} count={}", self.mode_count);
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "discretized mode",
                "milli-bin counts of column 0; ties take the smaller key",
                format!("mode={before:.6e}"),
                format!("mode={after:.6e}"),
            ),
        )
    }
}

/// Expanding maximum (river `stats.Peak`).
#[derive(Clone, Debug)]
pub struct OnlinePeak {
    peak: f64,
    n_seen: u64,
    updates: u64,
}

impl Default for OnlinePeak {
    fn default() -> Self {
        Self {
            peak: f64::NEG_INFINITY,
            n_seen: 0,
            updates: 0,
        }
    }
}

impl OnlinePeak {
    /// Empty peak tracker.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current peak, or NaN before the first finite value.
    pub fn score(&self) -> f64 {
        if self.n_seen == 0 {
            f64::NAN
        } else {
            self.peak
        }
    }
}

impl PartialFit for OnlinePeak {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let before = self.score();
        for i in 0..x.nrows() {
            let v = x.get(i, 0);
            if !v.is_finite() {
                continue;
            }
            if v > self.peak {
                self.peak = v;
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let after = self.score();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n_seen >= 1;
        q.warmup = self.n_seen < 1;
        q.explanation = format!("OnlinePeak={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "expanding maximum",
                "running max of column 0",
                format!("peak={before:.6e}"),
                format!("peak={after:.6e}"),
            ),
        )
    }
}

/// Streaming standard error of the mean (river `stats.SEM`).
#[derive(Clone, Debug, Default)]
pub struct OnlineSem {
    n: f64,
    mean: f64,
    m2: f64,
    updates: u64,
}

impl OnlineSem {
    /// Empty SEM accumulator.
    pub fn new() -> Self {
        Self::default()
    }

    /// \(s/\sqrt{n}\), or NaN during warmup.
    pub fn score(&self) -> f64 {
        if self.n < 2.0 {
            return f64::NAN;
        }
        let var = self.m2 / (self.n - 1.0);
        if var < 0.0 {
            f64::NAN
        } else {
            var.sqrt() / self.n.sqrt()
        }
    }
}

impl PartialFit for OnlineSem {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let before = self.score();
        for i in 0..x.nrows() {
            let v = x.get(i, 0);
            if !v.is_finite() {
                continue;
            }
            self.n += 1.0;
            let d = v - self.mean;
            self.mean += d / self.n;
            self.m2 += d * (v - self.mean);
        }
        self.updates += 1;
        let after = self.score();
        let mut q =
            IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n as u64);
        q.effective_sample_size = self.n;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n >= 2.0;
        q.warmup = self.n < 2.0;
        q.explanation = format!("OnlineSem={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "standard error of the mean",
                "Welford s / √n of column 0",
                format!("sem={before:.6e}"),
                format!("sem={after:.6e}"),
            ),
        )
    }
}

/// Windowed Spearman rank correlation (river `stats.SpearmanCorr`).
///
/// Window length is not identification `p`.
#[derive(Clone, Debug, Default)]
pub struct OnlineSpearman {
    xs: Vec<f64>,
    ys: Vec<f64>,
    n_seen: u64,
    updates: u64,
}

impl OnlineSpearman {
    /// Empty rank-correlation window.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current Spearman ρ, or NaN during warmup.
    pub fn score(&self) -> f64 {
        spearman_window(&self.xs, &self.ys)
    }
}

fn spearman_window(xs: &[f64], ys: &[f64]) -> f64 {
    let n = xs.len().min(ys.len());
    if n < 3 {
        return f64::NAN;
    }
    let rx = rank_average(xs);
    let ry = rank_average(ys);
    let mx = rx.iter().sum::<f64>() / n as f64;
    let my = ry.iter().sum::<f64>() / n as f64;
    let mut num = 0.0;
    let mut d1 = 0.0;
    let mut d2 = 0.0;
    for i in 0..n {
        let a = rx[i] - mx;
        let b = ry[i] - my;
        num += a * b;
        d1 += a * a;
        d2 += b * b;
    }
    if d1 <= 1e-18 || d2 <= 1e-18 {
        f64::NAN
    } else {
        num / (d1.sqrt() * d2.sqrt())
    }
}

fn rank_average(xs: &[f64]) -> Vec<f64> {
    let mut idx: Vec<usize> = (0..xs.len()).collect();
    idx.sort_by(|&a, &b| xs[a].partial_cmp(&xs[b]).unwrap_or(std::cmp::Ordering::Equal));
    let mut r = vec![0.0; xs.len()];
    let mut i = 0;
    while i < idx.len() {
        let mut j = i + 1;
        while j < idx.len() && (xs[idx[j]] - xs[idx[i]]).abs() <= 1e-15 {
            j += 1;
        }
        let avg = (i + j - 1) as f64 / 2.0 + 1.0;
        for &k in &idx[i..j] {
            r[k] = avg;
        }
        i = j;
    }
    r
}

impl PartialFit for OnlineSpearman {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        if x.ncols() < 2 && y.is_none() {
            ctx.push(
                Issue::builder(IssueCode::InsufficientSample)
                    .severity(Severity::Warning)
                    .message("OnlineSpearman needs two columns or an explicit y")
                    .build(),
            );
        }
        let before = self.score();
        for i in 0..x.nrows() {
            let a = x.get(i, 0);
            let b = if x.ncols() >= 2 {
                x.get(i, 1)
            } else if let Some(y) = y {
                if i < y.len() {
                    y[i]
                } else {
                    f64::NAN
                }
            } else {
                f64::NAN
            };
            if !a.is_finite() || !b.is_finite() {
                continue;
            }
            self.xs.push(a);
            self.ys.push(b);
            if self.xs.len() > 256 {
                self.xs.remove(0);
                self.ys.remove(0);
            }
            self.n_seen += 1;
        }
        self.updates += 1;
        let after = self.score();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.xs.len() as f64;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.xs.len() >= 3;
        q.warmup = self.xs.len() < 3;
        q.explanation = format!("OnlineSpearman={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "windowed Spearman ρ",
                "average ranks of column 0 vs column 1 or y; window length is not p",
                format!("rho={before:.6e}"),
                format!("rho={after:.6e}"),
            ),
        )
    }
}

/// Streaming Hill tail-index on the upper order statistics.
///
/// Reservoir size is not identification `p`.
#[derive(Clone, Debug)]
pub struct HillSketch {
    /// Number of upper order statistics kept.
    pub k: usize,
    heap: Vec<f64>,
    n_seen: u64,
    updates: u64,
}

impl Default for HillSketch {
    fn default() -> Self {
        Self {
            k: 8,
            heap: Vec::new(),
            n_seen: 0,
            updates: 0,
        }
    }
}

impl HillSketch {
    /// Hill reservoir of size `k`.
    pub fn new(k: usize) -> Self {
        Self {
            k: k.max(3),
            ..Self::default()
        }
    }

    /// Hill \(\xi\), or NaN during warmup.
    pub fn score(&self) -> f64 {
        let k = self.k.max(3).min(self.heap.len());
        if k < 3 {
            return f64::NAN;
        }
        let mut xs = self.heap.clone();
        xs.sort_by(|a, b| b.partial_cmp(a).unwrap_or(std::cmp::Ordering::Equal));
        let floor = xs[k - 1].max(1e-12);
        let mut s = 0.0;
        for v in xs.iter().take(k) {
            s += (v / floor).ln();
        }
        s / k as f64
    }
}

impl PartialFit for HillSketch {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let before = self.score();
        let cap = self.k.max(3);
        for i in 0..x.nrows() {
            let v = x.get(i, 0).abs();
            if !v.is_finite() || v <= 0.0 {
                continue;
            }
            self.heap.push(v);
            self.n_seen += 1;
        }
        if self.heap.len() > cap * 4 {
            self.heap
                .sort_by(|a, b| b.partial_cmp(a).unwrap_or(std::cmp::Ordering::Equal));
            self.heap.truncate(cap);
        }
        self.updates += 1;
        let after = self.score();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.heap.len().min(cap) as f64;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.heap.len() >= 3;
        q.warmup = self.heap.len() < 3;
        q.explanation = format!("HillSketch xi={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "Hill tail index",
                "mean log-excess of the largest |x| over the k-th order statistic",
                format!("xi={before:.6e}"),
                format!("xi={after:.6e}"),
            ),
        )
    }
}

