impl PartialFit for RollingAccuracy {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no y for RollingAccuracy"),
            );
        };
        let before = self.score();
        let cap = self.window.max(1);
        for i in 0..x.nrows().min(y.len()) {
            let pred = x.get(i, 0);
            let truth = y[i];
            if pred.is_finite() && truth.is_finite() {
                let ph: f64 = if pred > 0.5 { 1.0 } else { 0.0 };
                let th: f64 = if truth > 0.5 { 1.0 } else { 0.0 };
                let hit = if (ph - th).abs() < 0.5 { 1.0 } else { 0.0 };
                rolling_push(&mut self.buf, hit, cap);
                self.n_seen += 1;
            }
        }
        self.updates += 1;
        let after = self.score();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.buf.len() as f64;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = !self.buf.is_empty();
        q.warmup = self.buf.is_empty();
        q.explanation = format!("RollingAccuracy={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "windowed accuracy",
                "sliding 0-1 score of hard 0.5 on column 0 vs y; window is not identification p",
                format!("acc={before:.6e}"),
                format!("acc={after:.6e}"),
            ),
        )
    }
}

fn rolling_push_pair(pairs: &mut Vec<(f64, f64)>, pred: f64, truth: f64, cap: usize) {
    if pred.is_finite() && truth.is_finite() {
        pairs.push((pred, truth));
        if pairs.len() > cap {
            pairs.remove(0);
        }
    }
}

fn rolling_pair_metric<F>(
    session: &Session,
    name: &str,
    x: &Matrix,
    y: Option<&Vector>,
    window: usize,
    pairs: &mut Vec<(f64, f64)>,
    n_seen: &mut u64,
    updates: &mut u64,
    score: F,
    what: &str,
    why: &str,
) -> Result<Qualified<IncrementalExplain>>
where
    F: Fn(&[(f64, f64)]) -> f64,
{
    let mut ctx = FitCtx::with_session(session.child("partial_fit"));
    inspect_online_xy(&mut ctx, x, y);
    let Some(y) = y else {
        ctx.push(Issue::builder(IssueCode::MissingTarget).build());
        return finish_explain(
            ctx,
            reject_explain(*updates, x.nrows(), *n_seen, "missing target for rolling metric"),
        );
    };
    let before = score(pairs);
    let cap = window.max(1);
    for i in 0..x.nrows().min(y.len()) {
        rolling_push_pair(pairs, x.get(i, 0), y[i], cap);
        if x.get(i, 0).is_finite() && y[i].is_finite() {
            *n_seen += 1;
        }
    }
    *updates += 1;
    let after = score(pairs);
    let mut q = IncrementalQuality::new(updates.saturating_sub(1), x.nrows(), *n_seen);
    q.effective_sample_size = pairs.len() as f64;
    q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
        (after - before).abs()
    } else {
        0.0
    });
    q.information_gain = Some(x.nrows() as f64);
    q.still_identified = !pairs.is_empty() && after.is_finite();
    q.warmup = pairs.is_empty();
    q.explanation = format!("{name}={after:.6e}");
    flag_info(&mut ctx, &q);
    finish_explain(
        ctx,
        IncrementalExplain::from_quality(
            q,
            what,
            why,
            format!("{name}={before:.6e}"),
            format!("{name}={after:.6e}"),
        ),
    )
}

fn window_hard_counts(pairs: &[(f64, f64)]) -> (f64, f64, f64, f64) {
    let mut tp = 0.0_f64;
    let mut fp = 0.0_f64;
    let mut tn = 0.0_f64;
    let mut fn_ = 0.0_f64;
    for &(pred, truth) in pairs {
        let p = pred > 0.5;
        let t = truth > 0.5;
        match (p, t) {
            (true, true) => tp += 1.0,
            (true, false) => fp += 1.0,
            (false, false) => tn += 1.0,
            (false, true) => fn_ += 1.0,
        }
    }
    (tp, fp, tn, fn_)
}

fn window_f1(pairs: &[(f64, f64)]) -> f64 {
    let (tp, fp, _, fn_) = window_hard_counts(pairs);
    let den = 2.0 * tp + fp + fn_;
    if den <= 0.0 {
        f64::NAN
    } else {
        2.0 * tp / den
    }
}

fn window_precision(pairs: &[(f64, f64)]) -> f64 {
    let (tp, fp, _, _) = window_hard_counts(pairs);
    let den = tp + fp;
    if den <= 0.0 {
        f64::NAN
    } else {
        tp / den
    }
}

fn window_recall(pairs: &[(f64, f64)]) -> f64 {
    let (tp, _, _, fn_) = window_hard_counts(pairs);
    let den = tp + fn_;
    if den <= 0.0 {
        f64::NAN
    } else {
        tp / den
    }
}

fn window_r2(pairs: &[(f64, f64)]) -> f64 {
    if pairs.len() < 2 {
        return f64::NAN;
    }
    let n = pairs.len() as f64;
    let mut sse = 0.0_f64;
    let mut sy = 0.0_f64;
    let mut sy2 = 0.0_f64;
    for &(pred, truth) in pairs {
        let e = pred - truth;
        sse += e * e;
        sy += truth;
        sy2 += truth * truth;
    }
    let mean = sy / n;
    let sst = sy2 - n * mean * mean;
    if sst.abs() <= 1e-15 {
        f64::NAN
    } else {
        1.0 - sse / sst
    }
}

fn window_cohen(pairs: &[(f64, f64)]) -> f64 {
    let (tp, fp, tn, fn_) = window_hard_counts(pairs);
    let n = tp + fp + tn + fn_;
    if n <= 0.0 {
        return f64::NAN;
    }
    let po = (tp + tn) / n;
    let pe = ((tn + fp) * (tn + fn_) + (fn_ + tp) * (fp + tp)) / (n * n);
    if (1.0 - pe).abs() <= 1e-18 {
        f64::NAN
    } else {
        (po - pe) / (1.0 - pe)
    }
}

fn window_balanced(pairs: &[(f64, f64)]) -> f64 {
    let (tp, fp, tn, fn_) = window_hard_counts(pairs);
    let pos = tp + fn_;
    let neg = tn + fp;
    if pos <= 0.0 || neg <= 0.0 {
        f64::NAN
    } else {
        0.5 * (tp / pos + tn / neg)
    }
}

fn window_fbeta(pairs: &[(f64, f64)], beta: f64) -> f64 {
    let (tp, fp, _, fn_) = window_hard_counts(pairs);
    let b2 = beta * beta;
    let den = (1.0 + b2) * tp + b2 * fn_ + fp;
    if den <= 0.0 {
        f64::NAN
    } else {
        (1.0 + b2) * tp / den
    }
}

fn window_jaccard(pairs: &[(f64, f64)]) -> f64 {
    let mut inter = 0.0_f64;
    let mut union = 0.0_f64;
    for &(pred, truth) in pairs {
        let a = pred.round() != 0.0;
        let b = truth.round() != 0.0;
        if a && b {
            inter += 1.0;
        }
        if a || b {
            union += 1.0;
        }
    }
    if union <= 0.0 {
        f64::NAN
    } else {
        inter / union
    }
}

fn window_hamming(pairs: &[(f64, f64)]) -> f64 {
    if pairs.is_empty() {
        return f64::NAN;
    }
    let mut bad = 0.0_f64;
    for &(pred, truth) in pairs {
        if pred.round() != truth.round() {
            bad += 1.0;
        }
    }
    bad / pairs.len() as f64
}

fn window_smape(pairs: &[(f64, f64)]) -> f64 {
    if pairs.is_empty() {
        return f64::NAN;
    }
    let mut acc = 0.0_f64;
    let mut n = 0.0_f64;
    for &(pred, truth) in pairs {
        let den = pred.abs() + truth.abs();
        if den > 1e-12 {
            acc += 2.0 * (pred - truth).abs() / den;
            n += 1.0;
        }
    }
    if n <= 0.0 {
        f64::NAN
    } else {
        acc / n
    }
}

fn window_mcc(pairs: &[(f64, f64)]) -> f64 {
    let (tp, fp, tn, fn_) = window_hard_counts(pairs);
    let n = tp + fp + tn + fn_;
    if n <= 0.0 {
        return f64::NAN;
    }
    let den = ((tp + fp) * (tp + fn_) * (tn + fp) * (tn + fn_)).sqrt();
    if den < 1e-18 {
        0.0
    } else {
        (tp * tn - fp * fn_) / den
    }
}

fn window_roc_auc(pairs: &[(f64, f64)]) -> f64 {
    let mut pos = Vec::new();
    let mut neg = Vec::new();
    for &(s, y) in pairs {
        if y > 0.5 {
            pos.push(s);
        } else {
            neg.push(s);
        }
    }
    if pos.is_empty() || neg.is_empty() {
        return f64::NAN;
    }
    let mut ge = 0.0_f64;
    for &p in &pos {
        for &n in &neg {
            if p > n {
                ge += 1.0;
            } else if (p - n).abs() < 1e-15 {
                ge += 0.5;
            }
        }
    }
    ge / (pos.len() * neg.len()) as f64
}

