/// Streaming lag-1 autocorrelation (river `stats.AutoCorr`).
#[derive(Clone, Debug, Default)]
pub struct OnlineAutoCorr {
    last: Option<f64>,
    n: f64,
    mx: f64,
    my: f64,
    c: f64,
    vx: f64,
    vy: f64,
    updates: u64,
}

impl OnlineAutoCorr {
    /// Empty lag-1 accumulator.
    pub fn new() -> Self {
        Self::default()
    }

    /// Current lag-1 correlation, or NaN during warmup.
    pub fn score(&self) -> f64 {
        if self.n < 2.0 {
            return f64::NAN;
        }
        let den = (self.vx * self.vy).sqrt();
        if den <= 1e-18 {
            f64::NAN
        } else {
            self.c / den
        }
    }
}

impl PartialFit for OnlineAutoCorr {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let before = self.score();
        for i in 0..x.nrows() {
            let v = x.get(i, 0);
            if !v.is_finite() {
                continue;
            }
            if let Some(prev) = self.last {
                self.n += 1.0;
                let dx = prev - self.mx;
                self.mx += dx / self.n;
                let dy = v - self.my;
                self.my += dy / self.n;
                self.c += dx * (v - self.my);
                self.vx += dx * (prev - self.mx);
                self.vy += dy * (v - self.my);
            }
            self.last = Some(v);
        }
        self.updates += 1;
        let after = self.score();
        let mut q =
            IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n as u64);
        q.effective_sample_size = self.n;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n >= 3.0;
        q.warmup = self.n < 3.0;
        q.explanation = format!("OnlineAutoCorr={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "lag-1 correlation",
                "Welford Pearson of consecutive column-0 values",
                format!("rho={before:.6e}"),
                format!("rho={after:.6e}"),
            ),
        )
    }
}

/// Streaming variance threshold (river `feature_selection.VarianceThreshold`).
#[derive(Clone, Debug)]
pub struct OnlineVarianceThreshold {
    /// Keep columns with sample variance above this.
    pub threshold: f64,
    n: Vec<f64>,
    mean: Vec<f64>,
    m2: Vec<f64>,
    n_features: usize,
    updates: u64,
}

impl Default for OnlineVarianceThreshold {
    fn default() -> Self {
        Self {
            threshold: 0.0,
            n: Vec::new(),
            mean: Vec::new(),
            m2: Vec::new(),
            n_features: 0,
            updates: 0,
        }
    }
}

impl OnlineVarianceThreshold {
    /// Threshold `t` (not identification `p`).
    pub fn new(threshold: f64) -> Self {
        Self {
            threshold,
            ..Self::default()
        }
    }
}

impl PartialFit for OnlineVarianceThreshold {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        if self.n_features == 0 {
            self.n_features = x.ncols();
            self.n = vec![0.0; x.ncols()];
            self.mean = vec![0.0; x.ncols()];
            self.m2 = vec![0.0; x.ncols()];
        } else if x.ncols() != self.n_features {
            ctx.push(
                Issue::builder(IssueCode::FeatureSpaceChangedOnline)
                    .message(format!(
                        "OnlineVarianceThreshold saw {} columns after init with {}",
                        x.ncols(),
                        self.n_features
                    ))
                    .build(),
            );
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), 0, "feature space changed"),
            );
        }
        let before = self
            .m2
            .iter()
            .zip(&self.n)
            .map(|(m2, n)| if *n > 1.0 { m2 / (n - 1.0) } else { 0.0 })
            .sum::<f64>();
        for j in 0..x.ncols() {
            for i in 0..x.nrows() {
                let v = x.get(i, j);
                if !v.is_finite() {
                    continue;
                }
                self.n[j] += 1.0;
                let d = v - self.mean[j];
                self.mean[j] += d / self.n[j];
                self.m2[j] += d * (v - self.mean[j]);
            }
        }
        self.updates += 1;
        let after = self
            .m2
            .iter()
            .zip(&self.n)
            .map(|(m2, n)| if *n > 1.0 { m2 / (n - 1.0) } else { 0.0 })
            .sum::<f64>();
        let kept = (0..self.n_features)
            .filter(|&j| {
                let n = self.n[j];
                n > 1.0 && self.m2[j] / (n - 1.0) > self.threshold
            })
            .count();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), 0);
        q.effective_sample_size = self.n.iter().copied().fold(0.0_f64, f64::max);
        q.parameter_delta_norm = Some((after - before).abs());
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = kept >= 1;
        q.warmup = self.n.iter().all(|n| *n < 2.0);
        q.explanation = format!("OnlineVarianceThreshold kept={kept}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "column variance update",
                "Welford variance per column; transform drops near-constants",
                format!("sumvar={before:.6e}"),
                format!("sumvar={after:.6e} kept={kept}"),
            ),
        )
    }
}

impl Transform for OnlineVarianceThreshold {
    fn transform(&self, x: &Matrix, session: &Session) -> Result<Qualified<Matrix>> {
        let mut ctx = FitCtx::with_session(session.child("transform"));
        inspect_online_xy(&mut ctx, x, None);
        let mut keep = Vec::new();
        for j in 0..x.ncols().min(self.n_features) {
            let n = self.n.get(j).copied().unwrap_or(0.0);
            let v = if n > 1.0 { self.m2[j] / (n - 1.0) } else { 0.0 };
            if v > self.threshold {
                keep.push(j);
            }
        }
        if keep.is_empty() {
            ctx.push(
                Issue::builder(IssueCode::NearZeroVariance)
                    .message("OnlineVarianceThreshold kept no columns; returning column 0")
                    .build(),
            );
            keep.push(0);
        }
        ctx.finish(Matrix::from_fn(x.nrows(), keep.len(), |i, j| {
            x.get(i, keep[j].min(x.ncols().saturating_sub(1)))
        }))
    }
}

/// Poisson-process feature inclusion (river `feature_selection.PoissonInclusion`).
///
/// Feature count is not identification `p`. A column is kept once a Uniform
/// draw falls below \(1-e^{-\lambda}\).
#[derive(Clone, Debug)]
pub struct PoissonInclusion {
    /// Inclusion rate \(\lambda\).
    pub rate: f64,
    keep: Vec<bool>,
    n_seen: u64,
    updates: u64,
    rng: Rng,
}

impl Default for PoissonInclusion {
    fn default() -> Self {
        Self {
            rate: 1.0,
            keep: Vec::new(),
            n_seen: 0,
            updates: 0,
            rng: Rng::new(41),
        }
    }
}

impl PoissonInclusion {
    /// Inclusion rate `rate` (not identification `p`).
    pub fn new(rate: f64) -> Self {
        Self {
            rate,
            ..Self::default()
        }
    }
}

impl PartialFit for PoissonInclusion {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        if self.keep.is_empty() {
            self.keep = vec![false; x.ncols()];
        } else if self.keep.len() != x.ncols() {
            ctx.push(
                Issue::builder(IssueCode::FeatureSpaceChangedOnline)
                    .message(format!(
                        "PoissonInclusion saw {} columns; model has {}",
                        x.ncols(),
                        self.keep.len()
                    ))
                    .build(),
            );
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "feature space changed"),
            );
        }
        let before = self.keep.iter().filter(|k| **k).count();
        let lam = if self.rate.is_finite() && self.rate > 0.0 {
            self.rate
        } else {
            ctx.push(
                Issue::builder(IssueCode::InvalidWeight)
                    .severity(Severity::Warning)
                    .message(format!("PoissonInclusion rate={}; using 1", self.rate))
                    .build(),
            );
            1.0
        };
        let p = 1.0 - (-lam).exp();
        for j in 0..x.ncols() {
            if !self.keep[j] && self.rng.uniform() < p {
                self.keep[j] = true;
            }
        }
        self.n_seen += x.nrows() as u64;
        self.updates += 1;
        let after = self.keep.iter().filter(|k| **k).count();
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some((after as f64 - before as f64).abs());
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = after >= 1;
        q.warmup = after == 0;
        q.explanation = format!("PoissonInclusion kept={after}/{}", self.keep.len());
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "Poisson feature inclusion",
                "each unseen column is kept with probability 1-exp(-λ)",
                format!("kept={before}"),
                format!("kept={after}"),
            ),
        )
    }
}

impl Transform for PoissonInclusion {
    fn transform(&self, x: &Matrix, session: &Session) -> Result<Qualified<Matrix>> {
        let mut ctx = FitCtx::with_session(session.child("transform"));
        inspect_online_xy(&mut ctx, x, None);
        if self.keep.is_empty() {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(x.clone());
        }
        let idx: Vec<usize> = self
            .keep
            .iter()
            .enumerate()
            .filter(|(_, k)| **k)
            .map(|(j, _)| j)
            .collect();
        if idx.is_empty() {
            ctx.push(
                Issue::builder(IssueCode::NearZeroVariance)
                    .severity(Severity::Warning)
                    .message("PoissonInclusion kept no columns; returning the first")
                    .build(),
            );
            return ctx.finish(Matrix::from_fn(x.nrows(), 1, |i, _| x.get(i, 0)));
        }
        ctx.finish(Matrix::from_fn(x.nrows(), idx.len(), |i, j| {
            x.get(i, idx[j].min(x.ncols().saturating_sub(1)))
        }))
    }
}

/// Streaming univariate Gaussian (river `proba.Gaussian`).
#[derive(Clone, Debug, Default)]
pub struct OnlineGaussian {
    n: f64,
    mean: f64,
    m2: f64,
    updates: u64,
}

impl OnlineGaussian {
    /// Empty Gaussian.
    pub fn new() -> Self {
        Self::default()
    }

    /// Density at `x`, or NaN during warmup.
    pub fn pdf(&self, x: f64) -> f64 {
        if self.n < 2.0 {
            return f64::NAN;
        }
        let var = self.m2 / (self.n - 1.0);
        if var <= 1e-18 {
            return f64::NAN;
        }
        let z = (x - self.mean) / var.sqrt();
        (-0.5 * z * z).exp() / (std::f64::consts::TAU * var).sqrt()
    }
}

impl PartialFit for OnlineGaussian {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let before = self.mean;
        for i in 0..x.nrows() {
            let v = x.get(i, 0);
            if !v.is_finite() {
                continue;
            }
            self.n += 1.0;
            let d = v - self.mean;
            self.mean += d / self.n;
            self.m2 += d * (v - self.mean);
        }
        self.updates += 1;
        if self.n >= 2.0 && self.m2 / (self.n - 1.0) <= 1e-18 {
            ctx.push(
                Issue::builder(IssueCode::DegenerateDistribution)
                    .message("OnlineGaussian variance vanished; pdf is undefined")
                    .build(),
            );
        }
        let after = self.mean;
        let mut q =
            IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n as u64);
        q.effective_sample_size = self.n;
        q.parameter_delta_norm = Some((after - before).abs());
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n >= 2.0 && self.m2 > 1e-18;
        q.warmup = self.n < 2.0;
        q.explanation = format!("OnlineGaussian μ={after:.6e}");
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "Gaussian sufficient stats",
                "Welford mean and variance of column 0",
                format!("mu={before:.6e}"),
                format!("mu={after:.6e}"),
            ),
        )
    }
}

