/// Streaming Pareto Hill estimator on positive column 0 (river-style `proba`).
///
/// \(\hat\alpha = n / \sum\log(x_i/\hat x_{\min})\). Shape is not identification
/// `p`.
#[derive(Clone, Debug, Default)]
pub struct OnlinePareto {
    n: f64,
    sum_log: f64,
    xmin: f64,
    updates: u64,
}

impl OnlinePareto {
    /// Empty Pareto accumulator.
    pub fn new() -> Self {
        Self::default()
    }

    /// Hill shape, or NaN during warmup.
    pub fn alpha(&self) -> f64 {
        if self.n < 1.0 || !self.xmin.is_finite() || self.xmin <= 0.0 {
            return f64::NAN;
        }
        let den = self.sum_log - self.n * self.xmin.ln();
        if den <= 1e-18 {
            f64::NAN
        } else {
            self.n / den
        }
    }
}

impl PartialFit for OnlinePareto {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        let before = self.alpha();
        let mut nonpos = 0u64;
        for i in 0..x.nrows() {
            let v = x.get(i, 0);
            if !v.is_finite() {
                continue;
            }
            if v <= 0.0 {
                nonpos += 1;
                continue;
            }
            if self.n <= 0.0 || v < self.xmin {
                self.xmin = v;
            }
            self.n += 1.0;
            self.sum_log += v.ln();
        }
        if nonpos > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(Severity::Warning)
                    .message(format!(
                        "OnlinePareto skipped {nonpos} non-positive observations"
                    ))
                    .build(),
            );
        }
        self.updates += 1;
        let after = self.alpha();
        let mut q =
            IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n as u64);
        q.effective_sample_size = self.n;
        q.parameter_delta_norm = Some(if before.is_finite() && after.is_finite() {
            (after - before).abs()
        } else {
            0.0
        });
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.n >= 2.0 && after.is_finite();
        q.warmup = self.n < 2.0;
        q.explanation = format!("OnlinePareto α={after:.6e}");
        if q.warmup {
            ctx.push(
                Issue::builder(IssueCode::WarmupIncomplete)
                    .incremental(q.clone())
                    .message("OnlinePareto needs two positive observations")
                    .build(),
            );
        }
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "Pareto Hill shape",
                "running xmin and sum of log positives; shape is not p",
                format!("alpha={before:.6e}"),
                format!("alpha={after:.6e}"),
            ),
        )
    }
}

/// AdaMax linear regressor (river `optim.AdaMax`).
///
/// Infinity-norm second moment: \(u \leftarrow \max(\beta_2 u, |g|)\).
#[derive(Clone, Debug)]
pub struct AdaMaxRegressor {
    /// Step \(\eta\).
    pub learning_rate: f64,
    /// First-moment decay.
    pub beta1: f64,
    /// Infinity-norm decay.
    pub beta2: f64,
    /// Diagonal floor.
    pub eps: f64,
    /// Prepend an intercept column.
    pub fit_intercept: bool,
    coef: Vector,
    m: Vector,
    u: Vector,
    t: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for AdaMaxRegressor {
    fn default() -> Self {
        Self {
            learning_rate: 0.05,
            beta1: 0.9,
            beta2: 0.999,
            eps: 1e-8,
            fit_intercept: true,
            coef: Vector::zeros(0),
            m: Vector::zeros(0),
            u: Vector::zeros(0),
            t: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl AdaMaxRegressor {
    /// Default AdaMax regressor.
    pub fn new() -> Self {
        Self::default()
    }

    fn predict_row(&self, x: &Matrix, i: usize) -> f64 {
        let z = row_aug(x, i, self.fit_intercept);
        let n = z.len().min(self.coef.len());
        let mut s = 0.0;
        for j in 0..n {
            s += self.coef[j] * z[j];
        }
        s
    }
}

impl PartialFit for AdaMaxRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, y);
        let Some(y) = y else {
            ctx.push(Issue::builder(IssueCode::MissingTarget).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no target"),
            );
        };
        let dim = online_linear_dim(self.fit_intercept, x.ncols());
        if !self.initialized {
            self.coef = Vector::zeros(dim);
            self.m = Vector::zeros(dim);
            self.u = Vector::zeros(dim);
            self.initialized = true;
        } else if self.coef.len() != dim {
            ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
            return finish_explain(
                ctx,
                reject_explain(
                    self.updates,
                    x.nrows(),
                    self.n_seen,
                    "feature space changed",
                ),
            );
        }
        let before = self.coef.clone();
        let eta = if self.learning_rate.is_finite() && self.learning_rate > 0.0 {
            self.learning_rate
        } else {
            0.05
        };
        let b1 = self.beta1.clamp(0.0, 0.999);
        let b2 = self.beta2.clamp(0.0, 0.999);
        let eps = if self.eps.is_finite() && self.eps > 0.0 {
            self.eps
        } else {
            1e-8
        };
        let mut loss_before = 0.0;
        let mut loss_after = 0.0;
        for i in 0..x.nrows().min(y.len()) {
            if !y[i].is_finite() {
                continue;
            }
            let z = row_aug(x, i, self.fit_intercept);
            let pred = self.predict_row(x, i);
            let err = pred - y[i];
            loss_before += err * err;
            self.t += 1.0;
            let corr1 = 1.0 - b1.powf(self.t);
            for j in 0..dim {
                let g = err * z[j];
                self.m[j] = b1 * self.m[j] + (1.0 - b1) * g;
                let ug: f64 = g.abs();
                self.u[j] = (b2 * self.u[j]).max(ug);
                let mhat = self.m[j] / corr1.max(1e-18);
                self.coef[j] -= eta * mhat / (self.u[j] + eps);
            }
            let after = self.predict_row(x, i);
            let ea = after - y[i];
            loss_after += ea * ea;
            self.n_seen += 1;
        }
        self.updates += 1;
        let delta = self.coef.sub(&before);
        let expl = pack_linear_explain(
            &mut ctx,
            self.updates,
            x.nrows(),
            self.n_seen,
            &delta,
            loss_before,
            loss_after,
            self.n_seen >= dim as u64,
            self.n_seen < 4,
            "AdaMax linear weights",
            "the first moment is bias-corrected and scaled by the running ∞-norm of g",
        );
        finish_explain(ctx, expl)
    }
}

impl Predict for AdaMaxRegressor {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        ctx.finish(Vector::from_iter(
            (0..x.nrows()).map(|i| self.predict_row(x, i)),
        ))
    }
}

