/// Online Charbonnier / pseudo-Huber regressor (\(\sqrt{c^2+r^2}-c\)).
///
/// Scale \(c\) is not identification `p`. Distinct from [`OnlineHuberRegressor`]
/// (piecewise) and [`OnlineLogCoshRegressor`] (log-cosh).
#[derive(Clone, Debug)]
pub struct OnlineCharbonnierRegressor {
    /// Charbonnier scale \(c>0\). Not identification `p`.
    pub scale: f64,
    /// SGD step.
    pub learning_rate: f64,
    coef: Vector,
    intercept: f64,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for OnlineCharbonnierRegressor {
    fn default() -> Self {
        Self {
            scale: 1.0,
            learning_rate: 0.05,
            coef: Vector::zeros(0),
            intercept: 0.0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl OnlineCharbonnierRegressor {
    /// Charbonnier regressor with scale `scale`.
    pub fn new(scale: f64) -> Self {
        Self {
            scale,
            ..Self::default()
        }
    }
}

impl PartialFit for OnlineCharbonnierRegressor {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        let Some((y, lr)) = online_glm_prepare(
            &mut ctx,
            x,
            y,
            self.initialized,
            self.n_seen,
            &mut self.coef,
            self.learning_rate,
            "OnlineCharbonnierRegressor",
        ) else {
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "rejected Charbonnier update"),
            );
        };
        self.initialized = true;
        let c = if self.scale.is_finite() && self.scale > 0.0 {
            self.scale
        } else {
            1.0
        };
        let c2 = c * c;
        let before = self.coef.clone();
        let mut loss_before = 0.0_f64;
        let mut loss_after = 0.0_f64;
        let n_rows = x.nrows().min(y.len());
        for i in 0..n_rows {
            if !y[i].is_finite() {
                continue;
            }
            let mut eta = self.intercept;
            for j in 0..x.ncols() {
                eta += self.coef[j] * x.get(i, j);
            }
            let r = y[i] - eta;
            let nrm = (c2 + r * r).sqrt();
            loss_before += nrm - c;
            let g = -r / nrm;
            self.intercept -= lr * g;
            for j in 0..x.ncols() {
                self.coef[j] -= lr * g * x.get(i, j);
            }
            let mut ea = self.intercept;
            for j in 0..x.ncols() {
                ea += self.coef[j] * x.get(i, j);
            }
            let ra = y[i] - ea;
            loss_after += (c2 + ra * ra).sqrt() - c;
        }
        self.n_seen += n_rows as u64;
        self.updates += 1;
        let delta = self.coef.sub(&before);
        let expl = pack_linear_explain(
            &mut ctx,
            self.updates,
            n_rows,
            self.n_seen,
            &delta,
            loss_before,
            loss_after,
            self.n_seen as usize > x.ncols(),
            self.n_seen < 5,
            "online Charbonnier regressor",
            "SGD on sqrt(c^2+r^2)-c; the scale is not identification p",
        );
        finish_explain(ctx, expl)
    }
}

