/// Angle-based outlier detector (Kriegel, Schubert, Zimek ABOD).
///
/// Score is the variance of pairwise cosines of vectors from the query to a
/// reservoir of stored points. Distinct from [`Hbos`] (histograms), [`Ecod`]
/// (univariate tails), [`Copod`] (empirical copula), and [`Loda`].
#[derive(Clone, Debug)]
pub struct Abod {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for Abod {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl Abod {
    /// Empty ABOD detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let p = self.ncols.min(x.ncols());
        if p == 0 || self.rows.len() < 3 {
            return 0.0;
        }
        let n = self.rows.len();
        let mut cosines: Vec<f64> = Vec::new();
        for a in 0..n {
            if a >= self.rows.len() || self.rows[a].len() < p {
                continue;
            }
            for b in (a + 1)..n {
                if b >= self.rows.len() || self.rows[b].len() < p {
                    continue;
                }
                let mut dot = 0.0_f64;
                let mut na = 0.0_f64;
                let mut nb = 0.0_f64;
                let mut ok = true;
                for j in 0..p {
                    let z = x.get(i, j);
                    if !z.is_finite() {
                        ok = false;
                        break;
                    }
                    let ua = self.rows[a][j] - z;
                    let ub = self.rows[b][j] - z;
                    dot += ua * ub;
                    na += ua * ua;
                    nb += ub * ub;
                }
                if !ok {
                    continue;
                }
                let den = na.sqrt() * nb.sqrt();
                if den < 1e-18 {
                    continue;
                }
                cosines.push((dot / den).clamp(-1.0, 1.0));
            }
        }
        if cosines.len() < 2 {
            return 0.0;
        }
        let nf = cosines.len() as f64;
        let mut mean = 0.0_f64;
        for &c in &cosines {
            mean += c;
        }
        mean /= nf;
        let mut var = 0.0_f64;
        for &c in &cosines {
            let d = c - mean;
            var += d * d;
        }
        var / nf
    }
}

impl PartialFit for Abod {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        if x.ncols() == 0 {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no features"),
            );
        }
        let p = x.ncols();
        if !self.initialized {
            self.ncols = p;
            self.initialized = true;
        } else if self.ncols != p {
            ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "feature space changed"),
            );
        }
        let before_n = self.n_seen;
        for i in 0..x.nrows() {
            let mut row = Vec::with_capacity(p);
            let mut ok = true;
            for j in 0..p {
                let z = x.get(i, j);
                if !z.is_finite() {
                    ok = false;
                    break;
                }
                row.push(z);
            }
            if !ok {
                continue;
            }
            if self.rows.len() >= 64 {
                self.rows.remove(0);
            }
            self.rows.push(row);
        }
        self.n_seen += x.nrows() as u64;
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some((self.n_seen - before_n) as f64);
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.rows.len() >= 3;
        q.warmup = self.rows.len() < 3;
        q.explanation = format!("ABOD reservoir n={}", self.rows.len());
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "angle variance scores",
                "ABOD is variance of pairwise cosines; not COPOD/ECOD/HBOS",
                "previous reservoir",
                "updated reservoir",
            ),
        )
    }
}

