/// Subspace outlier detection (Kriegel, Kröger, Schubert, Zimek SOD).
///
/// Score is the mean 1-NN distance in random axis-aligned subspaces of the
/// reservoir. Distinct from [`Inne`] (full-space hyperspheres) and [`Abod`].
#[derive(Clone, Debug)]
pub struct Sod {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for Sod {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl Sod {
    /// Empty SOD detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let p = self.ncols.min(x.ncols());
        if p == 0 || self.rows.len() < 2 {
            return 0.0;
        }
        let nsub = p.min(4);
        let mut acc = 0.0_f64;
        let mut n = 0.0_f64;
        for s in 0..nsub {
            let j = s % p;
            let z = x.get(i, j);
            if !z.is_finite() {
                continue;
            }
            let mut best = f64::INFINITY;
            for row in &self.rows {
                if j >= row.len() {
                    continue;
                }
                let d = (z - row[j]).abs();
                if d < best {
                    best = d;
                }
            }
            if best.is_finite() {
                acc += best;
                n += 1.0;
            }
        }
        if n < 1.0 {
            0.0
        } else {
            acc / n
        }
    }
}

