/// Rank-1 PCA reconstruction anomaly on a reservoir.
///
/// When width \(\ge 2\), the score is \(\|(I-vv^\top)(x-\mu)\|^2\) after a
/// power-method first axis. In one dimension it is \((x-\mu)^2\). Distinct
/// from [`OnlinePca`] (Oja transform) and [`OnlineMahalanobis`].
#[derive(Clone, Debug)]
pub struct PcaAnomaly {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for PcaAnomaly {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl PcaAnomaly {
    /// Empty PCA anomaly detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn mean(&self) -> Vec<f64> {
        let p = self.ncols;
        let mut m = vec![0.0_f64; p];
        let mut n = 0.0_f64;
        for row in &self.rows {
            if row.len() < p {
                continue;
            }
            n += 1.0;
            for j in 0..p {
                m[j] += row[j];
            }
        }
        if n > 0.0 {
            for mj in &mut m {
                *mj /= n;
            }
        }
        m
    }

    fn first_axis(&self, mean: &[f64]) -> Vec<f64> {
        let p = self.ncols;
        let mut v = vec![0.0_f64; p];
        if p == 0 {
            return v;
        }
        v[0] = 1.0;
        for _ in 0..12 {
            let mut w = vec![0.0_f64; p];
            for row in &self.rows {
                if row.len() < p {
                    continue;
                }
                let mut proj = 0.0_f64;
                for j in 0..p {
                    proj += (row[j] - mean[j]) * v[j];
                }
                for j in 0..p {
                    w[j] += proj * (row[j] - mean[j]);
                }
            }
            let mut nrm = 0.0_f64;
            for wj in &w {
                nrm += wj * wj;
            }
            nrm = nrm.sqrt();
            if nrm < 1e-18 {
                break;
            }
            for j in 0..p {
                v[j] = w[j] / nrm;
            }
        }
        v
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        if self.rows.len() < 2 || self.ncols == 0 {
            return 0.0;
        }
        let p = self.ncols.min(x.ncols());
        let mean = self.mean();
        if p == 1 {
            let z = x.get(i, 0);
            if !z.is_finite() {
                return 0.0;
            }
            let d = z - mean[0];
            return d * d;
        }
        let v = self.first_axis(&mean);
        let mut centered = vec![0.0_f64; p];
        for j in 0..p {
            let z = x.get(i, j);
            if !z.is_finite() {
                return 0.0;
            }
            centered[j] = z - mean[j];
        }
        let mut proj = 0.0_f64;
        for j in 0..p {
            proj += centered[j] * v[j];
        }
        let mut s = 0.0_f64;
        for j in 0..p {
            let r = centered[j] - proj * v[j];
            s += r * r;
        }
        s
    }
}

