/// Median \(k\)-NN anomaly (median of \(k\) distances).
///
/// Distinct from [`KnnAnomaly`] (arithmetic mean) and [`Knnw`] (harmonic mean).
#[derive(Clone, Debug)]
pub struct KnnMedian {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for KnnMedian {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl KnnMedian {
    /// Empty median \(k\)-NN detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn dist_row(&self, x: &Matrix, i: usize, row: &[f64]) -> f64 {
        let p = self.ncols.min(x.ncols()).min(row.len());
        let mut s = 0.0_f64;
        for j in 0..p {
            let z = x.get(i, j);
            if !z.is_finite() {
                return f64::INFINITY;
            }
            let d = z - row[j];
            s += d * d;
        }
        s.sqrt()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        if self.rows.len() < 3 || self.ncols == 0 {
            return 0.0;
        }
        let k = 5.min(self.rows.len().saturating_sub(1)).max(1);
        let mut ds: Vec<f64> = self
            .rows
            .iter()
            .map(|row| self.dist_row(x, i, row))
            .filter(|d| d.is_finite() && *d > 1e-15)
            .collect();
        if ds.len() < k {
            return 0.0;
        }
        ds.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let take = &ds[..k];
        if take.len() % 2 == 1 {
            take[take.len() / 2]
        } else {
            0.5 * (take[take.len() / 2 - 1] + take[take.len() / 2])
        }
    }
}

