/// Empirical-quantile tail anomaly on the first coordinate.
///
/// Score is \(-\log\min(\hat F(x),1-\hat F(x))\). Distinct from [`IqrAnomaly`]
/// (IQR fence) and [`Hbos`] (histogram bins).
#[derive(Clone, Debug)]
pub struct QuantileAnomaly {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for QuantileAnomaly {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl QuantileAnomaly {
    /// Empty empirical-quantile detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let y = x.get(i, 0);
        if !y.is_finite() || self.rows.len() < 4 {
            return 0.0;
        }
        let xs = reservoir_first_coords(&self.rows);
        if xs.len() < 4 {
            return 0.0;
        }
        let n = xs.len() as f64;
        let cdf = xs.iter().filter(|v| **v <= y).count() as f64 / n;
        let tail = cdf.min(1.0 - cdf).max(1.0 / (n + 1.0));
        -tail.ln()
    }
}

