/// Windowed MAD z-score on the first coordinate (last 8 reservoir points).
///
/// Distinct from [`WindowZscore`] (mean/sd) and [`Rod`] (full-reservoir
/// random projections).
#[derive(Clone, Debug)]
pub struct WindowMad {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for WindowMad {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl WindowMad {
    /// Empty windowed MAD detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let y = x.get(i, 0);
        if !y.is_finite() {
            return 0.0;
        }
        let xs = reservoir_first_coords(&self.rows);
        if xs.len() < 3 {
            return 0.0;
        }
        let start = xs.len().saturating_sub(8);
        let mut win = xs[start..].to_vec();
        let med = rod_median(&mut win);
        let mad = rod_mad(&win, med);
        (y - med).abs() / mad
    }
}

