fn chebyshev_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut m = 0.0_f64;
    for j in 0..p {
        m = m.max((a[j] - b[j]).abs());
    }
    m
}

/// Chebyshev (\(\ell_\infty\)) \(k\)-NN anomaly.
///
/// Score is the mean of the \(k\) smallest \(\max_j|x_j-y_j|\) distances.
/// Distinct from [`KnnAnomaly`] (Euclidean mean).
#[derive(Clone, Debug)]
pub struct LinfAnomaly {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for LinfAnomaly {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

