/// Windowed IQR anomaly on the first coordinate (last 8 reservoir points).
///
/// Distinct from [`IqrAnomaly`] (full reservoir) and [`WindowMad`] (MAD, not
/// IQR).
#[derive(Clone, Debug)]
pub struct WindowIqr {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for WindowIqr {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl WindowIqr {
    /// Empty windowed IQR detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let y = x.get(i, 0);
        if !y.is_finite() {
            return 0.0;
        }
        let xs = reservoir_first_coords(&self.rows);
        if xs.len() < 4 {
            return 0.0;
        }
        let start = xs.len().saturating_sub(8);
        let mut win = xs[start..].to_vec();
        if win.len() < 4 {
            return 0.0;
        }
        win.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let n = win.len();
        let q1 = win[n / 4];
        let q3 = win[(3 * n) / 4];
        let med = rod_median(&mut win);
        let iqr = (q3 - q1).max(1e-12);
        (y - med).abs() / iqr
    }
}

