/// Last-8 coefficient-of-variation anomaly.
///
/// Score is \(|x-\bar x_{w}|/(|\bar x_{w}|+\varepsilon)\) on the trailing
/// eight first-coordinates. Distinct from [`WindowZscore`] (divides by
/// local SD) and [`WindowRange`] (min-max span).
#[derive(Clone, Debug)]
pub struct WindowCv {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for WindowCv {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl WindowCv {
    /// Empty windowed CV detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let y = x.get(i, 0);
        if !y.is_finite() {
            return 0.0;
        }
        let xs = reservoir_first_coords(&self.rows);
        if xs.len() < 3 {
            return 0.0;
        }
        let start = xs.len().saturating_sub(8);
        let win = &xs[start..];
        let mut s = 0.0_f64;
        let mut n = 0.0_f64;
        for v in win {
            s += *v;
            n += 1.0;
        }
        if n < 1.0 {
            return 0.0;
        }
        let mean = s / n;
        (y - mean).abs() / mean.abs().max(1e-12)
    }
}

