/// Geometric-mean \(k\)-NN anomaly.
///
/// Score is \(\exp(\frac1k\sum_{t=1}^{k}\ln d_{(t)})\) of the \(k\) smallest
/// Euclidean distances. Distinct from [`KnnAnomaly`] (arithmetic mean),
/// [`SsdAnomaly`] (sum of squares), and [`EnergyAnomaly`].
#[derive(Clone, Debug)]
pub struct GeometricAnomaly {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for GeometricAnomaly {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl GeometricAnomaly {
    /// Empty geometric-mean \(k\)-NN detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        if self.rows.len() < 3 || self.ncols == 0 {
            return 0.0;
        }
        let p = self.ncols.min(x.ncols());
        let mut qrow = Vec::with_capacity(p);
        for j in 0..p {
            let z = x.get(i, j);
            if !z.is_finite() {
                return 0.0;
            }
            qrow.push(z);
        }
        let mut ds: Vec<f64> = self
            .rows
            .iter()
            .map(|row| euclid_rows(&qrow, row))
            .filter(|d| d.is_finite() && *d > 1e-15)
            .collect();
        if ds.is_empty() {
            return 0.0;
        }
        ds.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let kk = 5.min(ds.len());
        let mut sln = 0.0_f64;
        for t in 0..kk {
            sln += ds[t].ln();
        }
        (sln / kk as f64).exp()
    }
}

