/// Last-8 cubed z-score anomaly.
///
/// Score is \(|(x-\bar x_w)/s_w|^3\) on the trailing eight first-coordinates.
/// Distinct from [`WindowZscore`] (unsquared) and [`WindowTrimmed`]
/// (trimmed location).
#[derive(Clone, Debug)]
pub struct WindowSkew {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for WindowSkew {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl WindowSkew {
    /// Empty windowed cubed-z detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let y = x.get(i, 0);
        if !y.is_finite() {
            return 0.0;
        }
        let xs = reservoir_first_coords(&self.rows);
        if xs.len() < 3 {
            return 0.0;
        }
        let start = xs.len().saturating_sub(8);
        let win = &xs[start..];
        let mut s = 0.0_f64;
        let mut n = 0.0_f64;
        for v in win {
            s += *v;
            n += 1.0;
        }
        if n < 1.0 {
            return 0.0;
        }
        let mean = s / n;
        let mut ss = 0.0_f64;
        for v in win {
            let d = *v - mean;
            ss += d * d;
        }
        let sd = (ss / n).sqrt().max(1e-12);
        let z = (y - mean) / sd;
        z.abs().powi(3)
    }
}

