fn lorentzian_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        s += (1.0 + (a[j] - b[j]).abs()).ln();
    }
    s
}

