fn angular_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut num = 0.0_f64;
    let mut na = 0.0_f64;
    let mut nb = 0.0_f64;
    for j in 0..p {
        num += a[j] * b[j];
        na += a[j] * a[j];
        nb += b[j] * b[j];
    }
    let den = na.sqrt() * nb.sqrt();
    if den < 1e-18 {
        return if na < 1e-18 && nb < 1e-18 { 0.0 } else { 0.5 };
    }
    (num / den).clamp(-1.0, 1.0).acos() / std::f64::consts::PI
}

