/// Last-8 linear-trend residual anomaly.
///
/// Score is \(|x-(a+bt_{\mathrm{next}})|/s\) after OLS on the trailing eight
/// first-coordinates. Distinct from [`WindowZscore`] (no slope) and
/// [`WindowTrimmed`].
#[derive(Clone, Debug)]
pub struct WindowSlope {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for WindowSlope {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl WindowSlope {
    /// Empty windowed slope-residual detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let y = x.get(i, 0);
        if !y.is_finite() {
            return 0.0;
        }
        let xs = reservoir_first_coords(&self.rows);
        if xs.len() < 3 {
            return 0.0;
        }
        let start = xs.len().saturating_sub(8);
        let win = &xs[start..];
        let n = win.len() as f64;
        let mut st = 0.0_f64;
        let mut sy = 0.0_f64;
        let mut stt = 0.0_f64;
        let mut sty = 0.0_f64;
        for (k, v) in win.iter().enumerate() {
            let t = k as f64;
            st += t;
            sy += *v;
            stt += t * t;
            sty += t * *v;
        }
        let den = n * stt - st * st;
        if den.abs() < 1e-12 {
            return 0.0;
        }
        let b = (n * sty - st * sy) / den;
        let a = (sy - b * st) / n;
        let mut ss = 0.0_f64;
        for (k, v) in win.iter().enumerate() {
            let r = *v - (a + b * k as f64);
            ss += r * r;
        }
        let sd = (ss / n).sqrt().max(1e-12);
        (y - (a + b * n)).abs() / sd
    }
}

