fn dice_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut num = 0.0_f64;
    let mut na = 0.0_f64;
    let mut nb = 0.0_f64;
    for j in 0..p {
        num += a[j] * b[j];
        na += a[j] * a[j];
        nb += b[j] * b[j];
    }
    let den = na + nb;
    if den < 1e-18 {
        return 0.0;
    }
    (1.0 - 2.0 * num / den).max(0.0)
}

/// Dice \(k\)-NN anomaly.
///
/// Score is the mean of the \(k\) smallest
/// \(1-2\langle x,y\rangle/(\|x\|^2+\|y\|^2)\) distances.
