/// Last-8 harmonic-mean ratio anomaly.
///
/// Score is \(|x|/H_w\) where \(H_w\) is the harmonic mean of the trailing
/// eight absolute first-coordinates. Distinct from [`WindowRms`] (quadratic
/// mean) and [`HarmonicAnomaly`] (harmonic-mean \(k\)-NN).
#[derive(Clone, Debug)]
pub struct WindowHarmonic {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for WindowHarmonic {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl WindowHarmonic {
    /// Empty windowed harmonic-mean detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let y = x.get(i, 0);
        if !y.is_finite() {
            return 0.0;
        }
        let xs = reservoir_first_coords(&self.rows);
        if xs.len() < 3 {
            return 0.0;
        }
        let start = xs.len().saturating_sub(8);
        let win = &xs[start..];
        let mut inv = 0.0_f64;
        let mut n = 0.0_f64;
        for v in win {
            inv += 1.0 / v.abs().max(1e-12);
            n += 1.0;
        }
        if n < 1.0 {
            return 0.0;
        }
        let hmean = n / inv.max(1e-12);
        y.abs() / hmean.max(1e-12)
    }
}

