fn clark_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let den = a[j].abs() + b[j].abs();
        if den > 1e-18 {
            let r = (a[j] - b[j]) / den;
            s += r * r;
        }
    }
    s.sqrt()
}

