/// Last-8 median-ratio anomaly.
///
/// Score is \(|x|/M_w\) where \(M_w\) is the median of the trailing eight
/// absolute first-coordinates. Distinct from [`WindowMad`] (deviation from
/// the median) and [`OnlineMedian`] (global running median).
#[derive(Clone, Debug)]
pub struct WindowMedian {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for WindowMedian {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl WindowMedian {
    /// Empty windowed median detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let y = x.get(i, 0);
        if !y.is_finite() {
            return 0.0;
        }
        let xs = reservoir_first_coords(&self.rows);
        if xs.len() < 3 {
            return 0.0;
        }
        let start = xs.len().saturating_sub(8);
        let win = &xs[start..];
        let mut absv: Vec<f64> = win.iter().map(|v| v.abs()).collect();
        absv.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let mid = absv.len() / 2;
        let med = if absv.len() % 2 == 0 {
            0.5 * (absv[mid - 1] + absv[mid])
        } else {
            absv[mid]
        };
        y.abs() / med.max(1e-12)
    }
}

