fn wave_hedges_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let ma = a[j].abs().max(b[j].abs());
        if ma > 1e-18 {
            s += (a[j] - b[j]).abs() / ma;
        }
    }
    s
}

/// Wave Hedges \(k\)-NN anomaly.
///
/// Score is the mean of the \(k\) smallest
/// \(\sum |x_j-y_j|/\max(|x_j|,|y_j|)\) distances.
/// Distinct from [`CanberraAnomaly`] and [`GeometricAnomaly`].
