/// Windowed backward-difference anomaly with a runtime order and window.
///
/// The `k`-th backward difference is formed by iterating the first difference
/// `k` times (AGENTS.md §4.4). Binomial coefficients are never materialised.
/// `order` above `min(Policy::max_difference_order, 20)` is a [`signlred::Failure`]
/// (design parameter out of domain), not a numerical underflow warning.
///
/// v0.1 `WindowLag1..8` used a trailing window of 8 and reservoir cap 64;
/// construct `WindowLag::new(order, window_8)` for those representative cases.
#[derive(Clone, Debug)]
pub struct WindowLag {
    /// Backward-difference order \(k \ge 1\).
    pub order: NonZeroUsize,
    /// Trailing window used for the mean-absolute scale.
    pub window: NonZeroUsize,
    cap: usize,
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

/// Hard ceiling on [`WindowLag::order`]. `Policy::max_difference_order` cannot
/// raise the allowed order above this (AGENTS.md §4.4).
pub const MAX_DIFFERENCE_ORDER: usize = 20;

/// v0.1 score scale floor. This is not a density floor (R7).
const MEAN_ABS_FLOOR: f64 = 1e-12;

impl WindowLag {
    /// Windowed \(k\)-th difference detector.
    ///
    /// Construction always succeeds; [`PartialFit::partial_fit`] and
    /// [`Predict::predict`] fail when `order` exceeds the active policy.
    pub fn new(order: NonZeroUsize, window: NonZeroUsize) -> Self {
        let cap = window.get().saturating_add(order.get()).max(64);
        Self {
            order,
            window,
            cap,
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }

    /// Trailing window of 8, matching v0.1 `WindowLag1..8`.
    pub fn order(order: NonZeroUsize) -> Self {
        Self::new(order, NonZeroUsize::new(8).expect("8 ≠ 0"))
    }

    fn order_allowed(&self, policy: &signlred::Policy) -> bool {
        self.order.get() <= policy.max_difference_order.min(MAX_DIFFERENCE_ORDER)
    }

    fn reject_order(&self, ctx: &mut FitCtx) -> bool {
        if self.order_allowed(&ctx.policy) {
            return false;
        }
        let max = ctx.policy.max_difference_order.min(MAX_DIFFERENCE_ORDER);
        ctx.push(
            Issue::builder(IssueCode::Overparameterized)
                .severity(Severity::Error)
                .message(format!(
                    "difference order {} exceeds Policy::max_difference_order {} (hard cap {})",
                    self.order, max, MAX_DIFFERENCE_ORDER
                ))
                .metric("order", self.order.get() as f64)
                .metric("max_difference_order", max as f64)
                .build(),
        );
        true
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let y = x.get(i, 0);
        if !y.is_finite() {
            return 0.0;
        }
        let k = self.order.get();
        let w = self.window.get();
        let xs = reservoir_first_coords(&self.rows);
        if xs.len() < k {
            return 0.0;
        }
        let start = xs.len().saturating_sub(w.max(k));
        let win = &xs[start..];
        if win.len() < k {
            return 0.0;
        }
        let mut mean_abs = 0.0_f64;
        for v in win {
            mean_abs += v.abs();
        }
        mean_abs /= win.len() as f64;
        let mut cur = win.to_vec();
        cur.push(y);
        let delta = backward_difference(&cur, k);
        delta.abs() / mean_abs.max(MEAN_ABS_FLOOR)
    }
}

impl Default for WindowLag {
    fn default() -> Self {
        Self::order(NonZeroUsize::MIN)
    }
}

/// \(k\)-th backward difference of `series` by iterating first differences.
///
/// After `k` passes the remaining slice has length `n-k`; the last entry is
/// \(\Delta^k x_{n-1}\), matching the binomial form
/// \(\sum_{j=0}^{k}(-1)^j\binom{k}{j}x_{n-1-j}\) used by v0.1 `WindowLag1..8`.
pub(crate) fn backward_difference(series: &[f64], order: usize) -> f64 {
    if order == 0 {
        return series.last().copied().unwrap_or(0.0);
    }
    if series.len() <= order {
        return 0.0;
    }
    let mut cur = series.to_vec();
    for _ in 0..order {
        let mut nxt = Vec::with_capacity(cur.len().saturating_sub(1));
        for i in 1..cur.len() {
            nxt.push(cur[i] - cur[i - 1]);
        }
        cur = nxt;
    }
    cur.last().copied().unwrap_or(0.0)
}

impl PartialFit for WindowLag {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        if self.reject_order(&mut ctx) {
            return finish_explain(
                ctx,
                reject_explain(
                    self.updates,
                    x.nrows(),
                    self.n_seen,
                    "difference order exceeds Policy::max_difference_order",
                ),
            );
        }
        if x.ncols() == 0 {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no features"),
            );
        }
        let p = x.ncols();
        if !self.initialized {
            self.ncols = p;
            self.initialized = true;
        } else if self.ncols != p {
            ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "feature space changed"),
            );
        }
        let before_n = self.n_seen;
        let k = self.order.get();
        for i in 0..x.nrows() {
            let mut row = Vec::with_capacity(p);
            let mut ok = true;
            for j in 0..p {
                let z = x.get(i, j);
                if !z.is_finite() {
                    ok = false;
                    break;
                }
                row.push(z);
            }
            if !ok {
                continue;
            }
            if self.rows.len() >= self.cap {
                self.rows.remove(0);
            }
            self.rows.push(row);
        }
        self.n_seen += x.nrows() as u64;
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some((self.n_seen - before_n) as f64);
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.rows.len() >= k;
        q.warmup = self.rows.len() < k;
        q.explanation = format!(
            "window-lag order={} window={} reservoir n={}",
            k,
            self.window,
            self.rows.len()
        );
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "windowed backward-difference anomaly",
                "WindowLag uses an iterative k-th difference; order is a runtime parameter",
                "previous reservoir",
                "updated reservoir",
            ),
        )
    }
}

impl Predict for WindowLag {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        inspect_online_xy(&mut ctx, x, None);
        if self.reject_order(&mut ctx) {
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        ctx.finish(Vector::from_iter((0..x.nrows()).map(|i| self.score_row(x, i))))
    }
}

fn kulczynski_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut num = 0.0_f64;
    let mut den = 0.0_f64;
    for j in 0..p {
        num += (a[j] - b[j]).abs();
        den += a[j].abs().min(b[j].abs());
    }
    if den < 1e-18 {
        return 0.0;
    }
    num / den
}

