fn ruzicka_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut nmin = 0.0_f64;
    let mut nmax = 0.0_f64;
    for j in 0..p {
        nmin += a[j].abs().min(b[j].abs());
        nmax += a[j].abs().max(b[j].abs());
    }
    if nmax < 1e-18 {
        return 0.0;
    }
    1.0 - nmin / nmax
}

/// Ružička \(k\)-NN anomaly.
