/// Last-8 min-ratio anomaly.
///
/// Score is \(|x|/m_w\) where \(m_w\) is the minimum of the trailing eight
/// absolute first-coordinates. Distinct from [`WindowPeak`] (max ratio),
/// [`WindowMedian`], and [`WindowRange`].
#[derive(Clone, Debug)]
pub struct WindowMin {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for WindowMin {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl WindowMin {
    /// Empty windowed min-ratio detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let y = x.get(i, 0);
        if !y.is_finite() {
            return 0.0;
        }
        let xs = reservoir_first_coords(&self.rows);
        if xs.len() < 3 {
            return 0.0;
        }
        let start = xs.len().saturating_sub(8);
        let win = &xs[start..];
        let mut mn = f64::INFINITY;
        for v in win {
            let a = v.abs();
            if a < mn {
                mn = a;
            }
        }
        y.abs() / mn.max(1e-12)
    }
}

