fn taneja_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18);
        let v = b[j].abs().max(1e-18);
        let am = 0.5 * (u + v);
        let gm = (u * v).sqrt().max(1e-18);
        s += am * (am / gm).ln();
    }
    s.max(0.0)
}

/// Taneja \(k\)-NN anomaly.
///
/// Score is the mean of the \(k\) smallest raw Taneja distances
/// \(\sum\frac{|x|+|y|}{2}\log\frac{|x|+|y|}{2\sqrt{|x||y|}}\).
/// Distinct from [`taneja_distance`] (which \(\ell_1\)-normalises first) and
/// [`RuzickaAnomaly`].
#[derive(Clone, Debug)]
pub struct TanejaAnomaly {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for TanejaAnomaly {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl TanejaAnomaly {
    /// Empty Taneja \(k\)-NN detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        if self.rows.len() < 3 || self.ncols == 0 {
            return 0.0;
        }
        let p = self.ncols.min(x.ncols());
        let mut qrow = Vec::with_capacity(p);
        for j in 0..p {
            let z = x.get(i, j);
            if !z.is_finite() {
                return 0.0;
            }
            qrow.push(z);
        }
        let mut ds: Vec<f64> = self
            .rows
            .iter()
            .map(|row| taneja_rows(&qrow, row))
            .filter(|d| d.is_finite() && *d > 1e-15)
            .collect();
        if ds.is_empty() {
            return 0.0;
        }
        ds.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let kk = 5.min(ds.len());
        let mut s = 0.0_f64;
        for t in 0..kk {
            s += ds[t];
        }
        s / kk as f64
    }
}

