/// Last-8 mean-absolute-deviation anomaly.
///
/// Score is \(|x-\bar x_w|/\mathrm{MAD}_1\) on the trailing eight first-coordinates,
/// where \(\mathrm{MAD}_1\) is the mean absolute deviation from the window mean.
/// Distinct from [`WindowMad`] (median / MAD) and [`WindowZscore`] (mean / SD).
#[derive(Clone, Debug)]
pub struct WindowAbsdev {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for WindowAbsdev {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl WindowAbsdev {
    /// Empty windowed mean-absolute-deviation detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let y = x.get(i, 0);
        if !y.is_finite() {
            return 0.0;
        }
        let xs = reservoir_first_coords(&self.rows);
        if xs.len() < 3 {
            return 0.0;
        }
        let start = xs.len().saturating_sub(8);
        let win = &xs[start..];
        let n = win.len() as f64;
        let mut mean = 0.0_f64;
        for v in win {
            mean += *v;
        }
        mean /= n;
        let mut mad1 = 0.0_f64;
        for v in win {
            mad1 += (*v - mean).abs();
        }
        mad1 /= n;
        (y - mean).abs() / mad1.max(1e-12)
    }
}

