fn kumar_johnson_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18);
        let v = b[j].abs().max(1e-18);
        let d2 = u * u - v * v;
        s += d2 * d2 / (2.0 * (u * v).powf(1.5));
    }
    s.max(0.0)
}

