/// Last-8 geometric-mean residual anomaly.
///
/// Score is \(|x|/\mathrm{GM}\) on the trailing eight first-coordinates,
/// where \(\mathrm{GM}\) is the geometric mean of absolute levels.
/// Distinct from [`WindowHarmonic`] (harmonic mean) and [`WindowRms`]
/// (quadratic mean).
#[derive(Clone, Debug)]
pub struct WindowGeom {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for WindowGeom {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl WindowGeom {
    /// Empty windowed geometric-mean detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let y = x.get(i, 0);
        if !y.is_finite() {
            return 0.0;
        }
        let xs = reservoir_first_coords(&self.rows);
        if xs.len() < 3 {
            return 0.0;
        }
        let start = xs.len().saturating_sub(8);
        let win = &xs[start..];
        let mut log_sum = 0.0_f64;
        for v in win {
            log_sum += v.abs().max(1e-18).ln();
        }
        let gm = (log_sum / win.len() as f64).exp();
        y.abs() / gm.max(1e-12)
    }
}

