fn vicis_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18);
        let v = b[j].abs().max(1e-18);
        let d = u - v;
        let m = u.min(v);
        s += d * d / (m * m);
    }
    s.max(0.0)
}

/// Vicis-symmetric \(k\)-NN anomaly.
///
/// Score is the mean of the \(k\) smallest raw Vicis-symmetric distances
/// \(\sum(x-y)^2/\min(|x|,|y|)^2\).
/// Distinct from the \(\ell_1\)-normalised Vicis metric and
/// [`AdditiveSymmetricAnomaly`].
