/// Last-8 variance residual anomaly.
///
/// Score is \(|x-\bar x_w|/s^2_w\) on the trailing eight first-coordinates.
/// Distinct from [`WindowZscore`] (\(|x-\bar x|/s\)) and [`WindowAbsdev`]
/// (\(|x-\bar x|/\mathrm{MAD}_1\)).
#[derive(Clone, Debug)]
pub struct WindowVar {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for WindowVar {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl WindowVar {
    /// Empty windowed variance detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let y = x.get(i, 0);
        if !y.is_finite() {
            return 0.0;
        }
        let xs = reservoir_first_coords(&self.rows);
        if xs.len() < 3 {
            return 0.0;
        }
        let start = xs.len().saturating_sub(8);
        let win = &xs[start..];
        let n = win.len() as f64;
        let mut mean = 0.0_f64;
        for v in win {
            mean += *v;
        }
        mean /= n;
        let mut var = 0.0_f64;
        for v in win {
            let d = *v - mean;
            var += d * d;
        }
        var /= n;
        (y - mean).abs() / var.max(1e-12)
    }
}

