fn topsoe_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18);
        let v = b[j].abs().max(1e-18);
        let m = u + v;
        s += u * (2.0 * u / m).ln() + v * (2.0 * v / m).ln();
    }
    s.max(0.0)
}

