fn hellinger_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().sqrt();
        let v = b[j].abs().sqrt();
        let d = u - v;
        s += d * d;
    }
    (0.5 * s).max(0.0).sqrt()
}

