/// Last-8 Shannon-entropy anomaly.
///
/// Score is \\(-\\sum p\\ln p\\) on the trailing eight first-coordinates after
/// \\(\\ell_1\\) normalisation of absolute levels.
/// Distinct from [`WindowGini`] (Gini) and [`WindowCv`] (coefficient of variation).
#[derive(Clone, Debug)]
pub struct WindowEntropy {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for WindowEntropy {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl WindowEntropy {
    /// Empty windowed entropy detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        let y = x.get(i, 0);
        if !y.is_finite() {
            return 0.0;
        }
        let xs = reservoir_first_coords(&self.rows);
        if xs.len() < 3 {
            return 0.0;
        }
        let start = xs.len().saturating_sub(8);
        let win = &xs[start..];
        let mut s = y.abs();
        for v in win {
            s += v.abs();
        }
        if s < 1e-18 {
            return 0.0;
        }
        let mut h = 0.0_f64;
        let py = (y.abs() / s).max(1e-18);
        h -= py * py.ln();
        for v in win {
            let p = (v.abs() / s).max(1e-18);
            h -= p * p.ln();
        }
        h.max(0.0)
    }
}

