fn jensen_shannon_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18);
        let v = b[j].abs().max(1e-18);
        let m = 0.5 * (u + v);
        s += 0.5 * u * (u / m).ln() + 0.5 * v * (v / m).ln();
    }
    s.max(0.0)
}

/// Jensen–Shannon \(k\)-NN anomaly.
///
/// Score is the mean of the \(k\) smallest raw (unsquared) Jensen–Shannon
/// divergences. Distinct from the \\(\\ell_1\\)-normalised JS *distance*
/// and [`HellingerAnomaly`].
#[derive(Clone, Debug)]
pub struct JensenShannonAnomaly {
    rows: Vec<Vec<f64>>,
    ncols: usize,
    n_seen: u64,
    updates: u64,
    initialized: bool,
}

impl Default for JensenShannonAnomaly {
    fn default() -> Self {
        Self {
            rows: Vec::new(),
            ncols: 0,
            n_seen: 0,
            updates: 0,
            initialized: false,
        }
    }
}

impl JensenShannonAnomaly {
    /// Empty Jensen–Shannon \(k\)-NN detector (reservoir cap 64).
    pub fn new() -> Self {
        Self::default()
    }

    fn score_row(&self, x: &Matrix, i: usize) -> f64 {
        if self.rows.len() < 3 || self.ncols == 0 {
            return 0.0;
        }
        let p = self.ncols.min(x.ncols());
        let mut qrow = Vec::with_capacity(p);
        for j in 0..p {
            let z = x.get(i, j);
            if !z.is_finite() {
                return 0.0;
            }
            qrow.push(z);
        }
        let mut ds: Vec<f64> = self
            .rows
            .iter()
            .map(|row| jensen_shannon_rows(&qrow, row))
            .filter(|d| d.is_finite() && *d > 1e-15)
            .collect();
        if ds.is_empty() {
            return 0.0;
        }
        ds.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let kk = 5.min(ds.len());
        let mut s = 0.0_f64;
        for t in 0..kk {
            s += ds[t];
        }
        s / kk as f64
    }
}

impl PartialFit for JensenShannonAnomaly {
    fn partial_fit(
        &mut self,
        x: &Matrix,
        _y: Option<&Vector>,
        session: &Session,
    ) -> Result<Qualified<IncrementalExplain>> {
        let mut ctx = FitCtx::with_session(session.child("partial_fit"));
        inspect_online_xy(&mut ctx, x, None);
        if x.ncols() == 0 {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "no features"),
            );
        }
        let p = x.ncols();
        if !self.initialized {
            self.ncols = p;
            self.initialized = true;
        } else if self.ncols != p {
            ctx.push(Issue::builder(IssueCode::FeatureSpaceChangedOnline).build());
            return finish_explain(
                ctx,
                reject_explain(self.updates, x.nrows(), self.n_seen, "feature space changed"),
            );
        }
        let before_n = self.n_seen;
        for i in 0..x.nrows() {
            let mut row = Vec::with_capacity(p);
            let mut ok = true;
            for j in 0..p {
                let z = x.get(i, j);
                if !z.is_finite() {
                    ok = false;
                    break;
                }
                row.push(z);
            }
            if !ok {
                continue;
            }
            if self.rows.len() >= 64 {
                self.rows.remove(0);
            }
            self.rows.push(row);
        }
        self.n_seen += x.nrows() as u64;
        self.updates += 1;
        let mut q = IncrementalQuality::new(self.updates.saturating_sub(1), x.nrows(), self.n_seen);
        q.effective_sample_size = self.n_seen as f64;
        q.parameter_delta_norm = Some((self.n_seen - before_n) as f64);
        q.information_gain = Some(x.nrows() as f64);
        q.still_identified = self.rows.len() >= 3;
        q.warmup = self.rows.len() < 3;
        q.explanation = format!("jensen-shannon-knn reservoir n={}", self.rows.len());
        flag_info(&mut ctx, &q);
        finish_explain(
            ctx,
            IncrementalExplain::from_quality(
                q,
                "Jensen-Shannon k-NN anomaly",
                "JensenShannonAnomaly is raw unsquared JS k-NN; not L1 JS distance or Hellinger",
                "previous reservoir",
                "updated reservoir",
            ),
        )
    }
}

impl Predict for JensenShannonAnomaly {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let mut ctx = FitCtx::with_session(session.child("predict"));
        inspect_online_xy(&mut ctx, x, None);
        if !self.initialized {
            ctx.push(Issue::builder(IssueCode::PartialFitBeforeInit).build());
            return ctx.finish(Vector::zeros(x.nrows()));
        }
        ctx.finish(Vector::from_iter((0..x.nrows()).map(|i| self.score_row(x, i))))
    }
}

fn squared_chord_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().sqrt();
        let v = b[j].abs().sqrt();
        let d = u - v;
        s += d * d;
    }
    s.max(0.0)
}

