fn pearson_chi_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs();
        let v = b[j].abs();
        let den = (u + v).max(1e-18);
        let d = u - v;
        s += d * d / den;
    }
    s.max(0.0)
}

