fn max_symmetric_chi_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut sx = 0.0_f64;
    let mut sy = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18);
        let v = b[j].abs().max(1e-18);
        let d = u - v;
        let d2 = d * d;
        sx += d2 / u;
        sy += d2 / v;
    }
    sx.max(sy).max(0.0)
}

