fn jensen_difference_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18);
        let v = b[j].abs().max(1e-18);
        let m = 0.5 * (u + v);
        s += m * m.ln() - 0.5 * (u * u.ln() + v * v.ln());
    }
    s.max(0.0)
}

