fn bray_curtis_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut num = 0.0_f64;
    let mut den = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs();
        let v = b[j].abs();
        num += (u - v).abs();
        den += u + v;
    }
    if den < 1e-18 {
        return 0.0;
    }
    (num / den).max(0.0)
}

