fn log_hassanat_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18).ln().abs();
        let v = b[j].abs().max(1e-18).ln().abs();
        let lo = u.min(v);
        let hi = u.max(v);
        if hi > 1e-18 {
            s += 1.0 - (1.0 + lo) / (1.0 + hi);
        }
    }
    s
}

