fn log_dice_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut num = 0.0_f64;
    let mut na = 0.0_f64;
    let mut nb = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18).ln();
        let v = b[j].abs().max(1e-18).ln();
        num += u * v;
        na += u * u;
        nb += v * v;
    }
    let den = na + nb;
    if den < 1e-18 {
        return 0.0;
    }
    (1.0 - 2.0 * num / den).max(0.0)
}

