fn log_clark_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18).ln().abs();
        let v = b[j].abs().max(1e-18).ln().abs();
        let den = u + v;
        if den > 1e-18 {
            let r = (u - v) / den;
            s += r * r;
        }
    }
    s.sqrt()
}

