fn log_jeffreys_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18).ln().abs().max(1e-18);
        let v = b[j].abs().max(1e-18).ln().abs().max(1e-18);
        s += (u - v) * (u / v).ln();
    }
    s.max(0.0)
}

/// Log–Jeffreys $k$-NN anomaly.
