fn log_kumar_hassebrook_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut num = 0.0_f64;
    let mut den = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18).ln().abs().max(1e-18);
        let v = b[j].abs().max(1e-18).ln().abs().max(1e-18);
        num += u * v;
        den += u * u + v * v - u * v;
    }
    if den < 1e-18 {
        return 0.0;
    }
    (1.0 - num / den).max(0.0)
}

