fn log_divergence_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18).ln().abs().max(1e-18);
        let v = b[j].abs().max(1e-18).ln().abs().max(1e-18);
        let den = (u + v).max(1e-18);
        let d = u - v;
        s += 2.0 * d * d / (den * den);
    }
    s.max(0.0)
}

