fn log_czekanowski_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut smin = 0.0_f64;
    let mut ssum = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18).ln().abs().max(1e-18);
        let v = b[j].abs().max(1e-18).ln().abs().max(1e-18);
        smin += if u < v { u } else { v };
        ssum += u + v;
    }
    if ssum < 1e-18 {
        return 0.0;
    }
    (1.0 - 2.0 * smin / ssum).max(0.0)
}

