fn log_bhattacharyya_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut s = 0.0_f64;
    let mut su = 0.0_f64;
    let mut sv = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18).ln().abs().max(1e-18);
        let v = b[j].abs().max(1e-18).ln().abs().max(1e-18);
        s += (u * v).sqrt();
        su += u;
        sv += v;
    }
    let den = (su * sv).sqrt().max(1e-18);
    let bc = (s / den).clamp(1e-18, 1.0);
    -bc.ln()
}

