fn log_angular_rows(a: &[f64], b: &[f64]) -> f64 {
    let p = a.len().min(b.len());
    let mut dot = 0.0_f64;
    let mut na = 0.0_f64;
    let mut nb = 0.0_f64;
    for j in 0..p {
        let u = a[j].abs().max(1e-18).ln().abs().max(1e-18);
        let v = b[j].abs().max(1e-18).ln().abs().max(1e-18);
        dot += u * v;
        na += u * u;
        nb += v * v;
    }
    let c = (dot / (na.sqrt().max(1e-18) * nb.sqrt().max(1e-18))).clamp(-1.0, 1.0);
    c.acos()
}

